  REVOKE EXECUTE ON FUNCTIONS FROM anon, PUBLIC;

-- 身份列序列只在数据库内部使用，源库里它们不对业务角色开放
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public
  REVOKE ALL ON SEQUENCES FROM anon, authenticated, service_role, PUBLIC;

