--

--
-- Name: act_workflow_task("uuid", "text", "text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."act_workflow_task"("p_task_id" "uuid", "p_action" "text", "p_comment" "text", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select app_private.current_app_user_id());
  v_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_actor_name text;
  v_comment text := nullif(btrim(coalesce(p_comment, '')), '');
  v_task public.wf_task;
  v_instance public.wf_instance;
  v_existing_instance_id uuid;
  v_existing_task_id uuid;
  v_action_id uuid;
  v_total_count integer;
  v_approved_count integer;
  v_rejected_count integer;
  v_pending_count integer;
  v_required_count integer;
  v_should_reject boolean := false;
begin
  if (select auth.uid()) is null or v_user_id is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;
  if p_action not in ('approve', 'reject') then
    raise exception '不支持的审批动作';
  end if;
  if p_action = 'reject' and v_comment is null then
    raise exception '驳回时必须填写原因';
  end if;
  if v_is_platform_super and coalesce(char_length(v_comment), 0) < 4 then
    raise exception '超管代审批原因至少填写4个字符';
  end if;
  if char_length(coalesce(v_comment, '')) > 500 then
    raise exception '审批意见不能超过500个字符';
  end if;

  -- Resolve the task first so a platform-super action uses the task tenant for
  -- idempotency, action audit rows, notifications, and business callbacks.
  select *
  into v_task
  from public.wf_task
  where id = p_task_id
    and (v_is_platform_super or tenant_id = v_tenant_id);

  if not found or (not v_is_platform_super and v_task.assignee_user_id <> v_user_id) then
    raise exception '待办不存在或当前用户不是审批人' using errcode = '42501';
  end if;

  if nullif(p_idempotency_key, '') is not null then
    select instance_id, task_id
    into v_existing_instance_id, v_existing_task_id
    from public.wf_action
    where tenant_id = v_task.tenant_id
      and idempotency_key = p_idempotency_key;

    if found then
      if v_existing_task_id is distinct from p_task_id then
        raise exception '幂等键已被其他审批任务使用';
      end if;
      return v_existing_instance_id;
    end if;
  end if;

  -- Keep the established instance-before-task lock order for concurrent decisions.
  select *
  into v_instance
  from public.wf_instance
  where id = v_task.instance_id
  for update;

  select *
  into v_task
  from public.wf_task
  where id = p_task_id
    and (v_is_platform_super or tenant_id = v_tenant_id)
  for update;

  if not found or (not v_is_platform_super and v_task.assignee_user_id <> v_user_id) then
    raise exception '待办不存在或当前用户不是审批人' using errcode = '42501';
  end if;
  if v_task.status <> 'pending' then
    raise exception '该待办已经处理';
  end if;
  if v_instance.status <> 'running' or v_instance.current_node_key <> v_task.node_key then
    raise exception '流程已结束或待办节点已失效';
  end if;

  select coalesce(nullif(nick_name, ''), nullif(user_name, ''), user_email, id::text)
  into v_actor_name
  from public.sys_user
  where id = v_user_id;

  update public.wf_task
  set status = case when p_action = 'approve' then 'approved' else 'rejected' end,
      handled_at = now(),
      comment = v_comment
  where id = v_task.id;

  insert into public.wf_action(
    instance_id,
    task_id,
    node_key,
    node_name,
    action,
    actor_user_id,
    actor_name_snapshot,
    comment,
    metadata,
    idempotency_key,
    tenant_id
  ) values (
    v_instance.id,
    v_task.id,
    v_task.node_key,
    v_task.node_name,
    p_action,
    v_user_id,
    v_actor_name,
    v_comment,
    jsonb_build_object(
      'source', case when v_is_platform_super then 'platform_super_override' else 'workflow_workbench' end,
      'operatorType', case when v_is_platform_super then 'platform_super_override' else 'assignee' end,
      'originalAssigneeUserId', v_task.assignee_user_id,
      'originalAssigneeName', v_task.assignee_name_snapshot,
      'taskTenantId', v_task.tenant_id
    ),
    nullif(p_idempotency_key, ''),
    v_task.tenant_id
  ) returning id into v_action_id;

  if v_is_platform_super and v_task.assignee_user_id <> v_user_id then
    perform app_private.enqueue_user_notification(
      v_task.assignee_user_id,
      v_task.tenant_id,
      'message',
      '平台超级管理员已代为处理待办',
      v_actor_name || case when p_action = 'approve' then '代为通过了' else '代为驳回了' end
        || '“' || v_instance.business_title || '”'
        || coalesce('：' || v_comment, ''),
      case when p_action = 'approve' then 'success' else 'danger' end,
      'workflow_super_override',
      v_action_id,
      v_instance.business_type,
      v_instance.business_id,
      v_instance.id,
      '/workflow/workbench',
      jsonb_build_object('tab', 'handled', 'instanceId', v_instance.id)
    );
  end if;

  select
    count(*)::integer,
    count(*) filter (where status = 'approved')::integer,
    count(*) filter (where status = 'rejected')::integer,
    count(*) filter (where status = 'pending')::integer
  into v_total_count, v_approved_count, v_rejected_count, v_pending_count
  from public.wf_task
  where instance_id = v_instance.id
    and node_key = v_task.node_key;

  v_required_count := case v_task.approval_mode
    when 'any' then 1
    when 'all' then v_total_count
    else ceil(v_total_count * v_task.approval_threshold_percent / 100.0)::integer
  end;

  if p_action = 'reject' then
    v_should_reject := v_task.reject_veto_enabled
      or (v_approved_count + v_pending_count < v_required_count);
  end if;

  if v_should_reject then
    update public.wf_task
    set status = 'cancelled', handled_at = now(), comment = '同节点审批结论已确定为驳回'
    where instance_id = v_instance.id
      and node_key = v_task.node_key
      and status = 'pending';

    update public.wf_instance
    set status = 'rejected',
        finished_at = now(),
        finish_comment = v_comment,
        current_node_key = null,
        current_node_name = null,
        row_version = row_version + 1
    where id = v_instance.id;

    perform app_private.apply_workflow_business_status(
      v_instance.business_type, v_instance.business_id, 'rejected', v_actor_name, v_comment
    );
    return v_instance.id;
  end if;

  if v_approved_count < v_required_count then
    return v_instance.id;
  end if;

  update public.wf_task
  set status = 'cancelled', handled_at = now(), comment = '同节点已达到通过条件'
  where instance_id = v_instance.id
    and node_key = v_task.node_key
    and status = 'pending';

  perform app_private.activate_next_workflow_node(v_instance.id, v_task.node_order);
  return v_instance.id;
end;
$$;


ALTER FUNCTION "app_private"."act_workflow_task"("p_task_id" "uuid", "p_action" "text", "p_comment" "text", "p_idempotency_key" "text") OWNER TO "postgres";

--

--
-- Name: activate_next_workflow_node("uuid", integer); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."activate_next_workflow_node"("p_instance_id" "uuid", "p_after_order" integer) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance public.wf_instance;
  v_config jsonb;
  v_node jsonb;
  v_original_assignee record;
  v_assignment record;
  v_assignee_count integer;
  v_mode text;
  v_candidate_count integer := 0;
begin
  select i.* into v_instance
  from public.wf_instance i
  where i.id = p_instance_id
  for update;

  if not found then raise exception '流程实例不存在'; end if;

  select v.config into v_config
  from public.wf_version v
  where v.id = v_instance.version_id;

  for v_node in
    select value
    from jsonb_array_elements(v_config -> 'nodes')
    where (value ->> 'order')::integer > p_after_order
    order by (value ->> 'order')::integer
  loop
    v_candidate_count := v_candidate_count + 1;

    if not app_private.workflow_condition_matches(v_instance.context_snapshot, v_node) then
      insert into public.wf_action(
        instance_id, node_key, node_name, action, actor_name_snapshot, comment, tenant_id
      ) values (
        v_instance.id, v_node ->> 'key', v_node ->> 'name', 'auto_skip',
        '系统', '条件不满足，自动跳过', v_instance.tenant_id
      );
      continue;
    end if;

    v_mode := v_node ->> 'approvalMode';
    v_assignee_count := 0;

    for v_original_assignee in
      select * from app_private.resolve_workflow_assignees(
        v_instance.tenant_id, v_node, v_instance.initiator_user_id
      )
    loop
      select * into v_assignment
      from app_private.resolve_workflow_assignment(
        v_instance.tenant_id, v_original_assignee.user_id, now()
      );

      if not found then continue; end if;

      insert into public.wf_task(
        instance_id, node_key, node_name, node_order, approval_mode,
        approval_threshold_percent, reject_veto_enabled,
        assignee_user_id, assignee_name_snapshot,
        original_assignee_user_id, original_assignee_name_snapshot,
        assignment_source, delegation_id, assignment_reason,
        due_at, tenant_id
      ) values (
        v_instance.id, v_node ->> 'key', v_node ->> 'name',
        (v_node ->> 'order')::integer, v_mode,
        case when v_mode = 'any' then 1 when v_mode = 'all' then 100
          else (v_node ->> 'approvalThresholdPercent')::integer end,
        coalesce((v_node ->> 'rejectVetoEnabled')::boolean, true),
        v_assignment.assignee_user_id, v_assignment.assignee_name,
        v_original_assignee.user_id, v_original_assignee.user_name,
        v_assignment.assignment_source, v_assignment.delegation_id,
        case when v_assignment.delegation_id is null then null else '按有效委托自动分配' end,
        case when coalesce((v_node ->> 'dueHours')::integer, 0) > 0
          then now() + make_interval(hours => (v_node ->> 'dueHours')::integer) end,
        v_instance.tenant_id
      );
      v_assignee_count := v_assignee_count + 1;
    end loop;

    if v_assignee_count = 0 then
      raise exception '节点“%”没有可用审批人，请检查角色、人员、自审或委托配置', v_node ->> 'name';
    end if;

    update public.wf_instance
    set current_node_key = v_node ->> 'key',
        current_node_name = v_node ->> 'name',
        row_version = row_version + 1
    where id = v_instance.id;
    return;
  end loop;

  if v_candidate_count > 0
     and not coalesce((v_config ->> 'allowAutoApprove')::boolean, false) then
    raise exception '后续审批条件全部未命中，流程已安全阻断；请检查业务上下文或显式开启自动通过策略';
  end if;

  update public.wf_instance
  set status = 'approved', current_node_key = null, current_node_name = null,
      finished_at = now(), row_version = row_version + 1
  where id = v_instance.id;

  perform app_private.apply_workflow_business_status(
    v_instance.business_type, v_instance.business_id, 'approved', '系统', '流程全部节点已通过'
  );
end;
$$;


ALTER FUNCTION "app_private"."activate_next_workflow_node"("p_instance_id" "uuid", "p_after_order" integer) OWNER TO "postgres";

--

--
-- Name: apply_workflow_business_status("text", "uuid", "text", "text", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."apply_workflow_business_status"("p_business_type" "text", "p_business_id" "uuid", "p_status" "text", "p_actor" "text", "p_comment" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance public.wf_instance;
  v_outbox_id uuid;
begin
  select *
  into v_instance
  from public.wf_instance i
  where i.business_type = p_business_type
    and i.business_id = p_business_id
  order by i.create_time desc, i.id desc
  limit 1;

  if not found then
    raise exception '审批业务回调无法定位流程实例';
  end if;

  insert into public.wf_business_callback_outbox(
    tenant_id,
    instance_id,
    business_type,
    business_id,
    target_status,
    actor_name,
    callback_comment,
    payload,
    create_by,
    update_by
  ) values (
    v_instance.tenant_id,
    v_instance.id,
    p_business_type,
    p_business_id,
    p_status,
    coalesce(nullif(btrim(p_actor), ''), '系统'),
    nullif(btrim(coalesce(p_comment, '')), ''),
    jsonb_build_object(
      'instanceId', v_instance.id,
      'businessType', p_business_type,
      'businessId', p_business_id,
      'targetStatus', p_status
    ),
    coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text, 'workflow-engine'),
    coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text, 'workflow-engine')
  )
  on conflict (instance_id, target_status) do nothing
  returning id into v_outbox_id;

  if v_outbox_id is null then
    select o.id into v_outbox_id
    from public.wf_business_callback_outbox o
    where o.instance_id = v_instance.id
      and o.target_status = p_status;
  end if;

  perform app_private.attempt_workflow_business_callback(v_outbox_id, 'workflow-inline');
end;
$$;


ALTER FUNCTION "app_private"."apply_workflow_business_status"("p_business_type" "text", "p_business_id" "uuid", "p_status" "text", "p_actor" "text", "p_comment" "text") OWNER TO "postgres";

--

--
-- Name: assert_fms_voucher_ready("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."assert_fms_voucher_ready"("p_voucher_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_voucher public.fms_voucher%rowtype;
begin
  perform app_private.refresh_fms_voucher_totals(p_voucher_id);
  select * into v_voucher from public.fms_voucher where id = p_voucher_id;
  if v_voucher.line_count < 2 then
    raise exception using errcode = '23514', message = '凭证至少需要两条分录';
  end if;
  if v_voucher.total_debit <= 0 or v_voucher.total_debit <> v_voucher.total_credit then
    raise exception using errcode = '23514', message = '凭证借贷金额必须大于零且保持平衡';
  end if;
  if not exists (
    select 1 from public.fms_accounting_period period
    where period.id = v_voucher.accounting_period_id and period.status = 'open'
      and v_voucher.voucher_date between period.start_date and period.end_date
  ) then
    raise exception using errcode = '23514', message = '凭证所属会计期间未开放';
  end if;
  if exists (
    select 1 from public.fms_voucher_line line
    left join public.fms_subject subject on subject.id = line.subject_id and subject.is_enabled
    where line.voucher_id = p_voucher_id
      and (subject.id is null or exists (
        select 1 from public.fms_subject child where child.parent_id = line.subject_id
      ))
  ) then
    raise exception using errcode = '23514', message = '凭证包含已停用、无效或非末级科目';
  end if;
  if exists (
    select 1
    from public.fms_voucher_line line
    join public.fms_subject subject on subject.id = line.subject_id
    left join lateral (
      select coalesce(sum(allocation.amount), 0) as allocated_amount
      from public.fms_cash_flow_allocation allocation
      where allocation.voucher_line_id = line.id
    ) allocation on true
    where line.voucher_id = p_voucher_id
      and subject.cash_flow_required
      and allocation.allocated_amount <> greatest(line.debit_amount, line.credit_amount)
  ) then
    raise exception using errcode = '23514', message = '现金及现金等价物分录必须完成全额现金流量归集';
  end if;
end;
$$;


ALTER FUNCTION "app_private"."assert_fms_voucher_ready"("p_voucher_id" "uuid") OWNER TO "postgres";

--

--
-- Name: current_user_tenant_id(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."current_user_tenant_id"() RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_auth_tenant_id uuid := app_private.auth_user_tenant_id();
  v_requested_text text;
  v_requested_tenant_id uuid;
begin
  if not app_private.is_platform_super() then
    return v_auth_tenant_id;
  end if;

  v_requested_text := nullif(
    btrim(
      coalesce(
        current_setting('request.headers', true)::jsonb->>'x-art-tenant-scope',
        ''
      )
    ),
    ''
  );
  if v_requested_text is null then
    return v_auth_tenant_id;
  end if;

  begin
    v_requested_tenant_id := v_requested_text::uuid;
  exception
    when invalid_text_representation then
      raise exception '租户范围标识无效' using errcode = '22023';
  end;

  if not exists (
    select 1
    from public.sys_tenant tenant
    where tenant.id = v_requested_tenant_id
      and tenant.status = '1'
      and tenant.builtin_type is distinct from 'platform'
      and (
        tenant.service_start_date is null
        or tenant.service_start_date <= (now() at time zone 'Asia/Shanghai')::date
      )
      and (
        tenant.service_end_date is null
        or tenant.service_end_date >= (now() at time zone 'Asia/Shanghai')::date
      )
  ) then
    raise exception '所选租户不存在、已停用或不在服务期' using errcode = '22023';
  end if;

  return v_requested_tenant_id;
end;
$$;


ALTER FUNCTION "app_private"."current_user_tenant_id"() OWNER TO "postgres";

SET default_tablespace = '';

SET default_table_access_method = "heap";

--

--
-- Name: assert_wms_destination("uuid", "uuid", "uuid", "uuid", numeric, numeric); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."assert_wms_destination"("p_tenant_id" "uuid", "p_warehouse_id" "uuid", "p_bin_id" "uuid", "p_material_id" "uuid", "p_quantity" numeric, "p_area" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_w public.mdm_warehouse%rowtype; v_b public.mdm_warehouse_bin%rowtype; v_z public.mdm_warehouse_zone%rowtype;
 v_material public.mdm_material%rowtype; v_current_quantity numeric; v_current_area numeric; v_current_weight numeric;
begin
 select * into v_w from public.mdm_warehouse where id=p_warehouse_id and tenant_id=p_tenant_id;
 if not found or v_w.status<>'enabled' then raise exception '仓库不存在或已停用' using errcode='23514'; end if;
 select * into v_material from public.mdm_material where id=p_material_id and tenant_id=p_tenant_id;
 if not found or v_material.status<>'enabled' then raise exception '物料不存在或已停用' using errcode='23514'; end if;
 if not v_w.enable_locations then
  if p_bin_id is not null then raise exception '该仓库未启用仓位' using errcode='23514'; end if;
  return;
 end if;
 if p_bin_id is null then raise exception '请先选择库位' using errcode='23514'; end if;
 select * into v_b from public.mdm_warehouse_bin where id=p_bin_id and warehouse_id=p_warehouse_id and tenant_id=p_tenant_id for update;
 if not found or v_b.status<>'available' then raise exception '库位不可存放库存' using errcode='23514'; end if;
 if v_b.zone_id is not null then
  select * into v_z from public.mdm_warehouse_zone where id=v_b.zone_id and tenant_id=p_tenant_id for update;
  if not found or v_z.status<>'enabled' or v_z.abnormal then raise exception '所属库区不可存放库存' using errcode='23514'; end if;
  if v_z.category_id is not null and v_z.category_id is distinct from v_material.category_id then
   raise exception '物料分类与库区存放类型不匹配' using errcode='23514'; end if;
 end if;
 if v_b.fixed_material_id is not null and v_b.fixed_material_id<>p_material_id then
  raise exception '定容库位只能存放指定物料' using errcode='23514'; end if;
 if v_material.serial_management_enabled and not coalesce(v_b.supports_serial,false) then
  raise exception '序列号管控物料只能存放到支持 SN 的库位' using errcode='23514'; end if;
 select coalesce(sum(quantity),0),coalesce(sum(area_sqm),0),
  coalesce(sum(case when m.gross_weight is null then 0 else quantity*m.gross_weight end),0)
 into v_current_quantity,v_current_area,v_current_weight
 from public.wms_inventory_batch b
 join public.mdm_material m on m.id=b.material_id and m.tenant_id=b.tenant_id
 where b.tenant_id=p_tenant_id and b.bin_id=p_bin_id and b.quantity>0;
 if v_z.id is not null and not v_z.allow_mix and exists(
  select 1 from public.wms_inventory_batch stock
  join public.mdm_warehouse_bin location on location.id=stock.bin_id and location.tenant_id=stock.tenant_id
  where stock.tenant_id=p_tenant_id and stock.warehouse_id=p_warehouse_id and location.zone_id=v_z.id
    and stock.quantity>0 and stock.material_id<>p_material_id
 ) then raise exception '该库区不允许混放物料' using errcode='23514'; end if;
 if (v_w.single_sku_per_bin or not v_b.allow_mix)
  and exists(select 1 from public.wms_inventory_batch where tenant_id=p_tenant_id and bin_id=p_bin_id and quantity>0 and material_id<>p_material_id)
 then raise exception '该库位不允许混放物料' using errcode='23514'; end if;
 if v_b.max_quantity is not null and v_current_quantity+p_quantity>v_b.max_quantity then
  raise exception '库位数量超过上限' using errcode='23514'; end if;
 if v_b.max_area_sqm is not null and (p_area is null or v_current_area+p_area>v_b.max_area_sqm) then
  raise exception '库位面积缺失或超过上限' using errcode='23514'; end if;
 if v_b.max_weight_kg is not null and
   (v_material.gross_weight is null or v_current_weight+p_quantity*v_material.gross_weight>v_b.max_weight_kg)
 then raise exception '物料重量缺失或库位承重超过上限' using errcode='23514'; end if;
end $$;


ALTER FUNCTION "app_private"."assert_wms_destination"("p_tenant_id" "uuid", "p_warehouse_id" "uuid", "p_bin_id" "uuid", "p_material_id" "uuid", "p_quantity" numeric, "p_area" numeric) OWNER TO "postgres";

--

--
-- Name: assign_scm_sales_quotation_line_numbers(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."assign_scm_sales_quotation_line_numbers"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
begin
  if new.kind<>'sales_quotation' then return new; end if;
  select coalesce(jsonb_agg(
    case when nullif(line.value->>'line_no','') is null
      then jsonb_set(line.value,'{line_no}',to_jsonb((line.ordinality*10)::integer),true)
      else line.value end order by line.ordinality),'[]'::jsonb)
  into new.lines
  from jsonb_array_elements(new.lines) with ordinality line(value,ordinality);
  if exists (select 1 from jsonb_array_elements(new.lines) line
    where line->>'line_no' !~ '^[1-9][0-9]*$' or length(line->>'line_no')>9)
    or exists (select 1 from jsonb_array_elements(new.lines) line
      group by line->>'line_no' having count(*)>1) then
    raise exception '销售报价明细行号须为不重复的正整数' using errcode='23514';
  end if;
  return new;
end $_$;


ALTER FUNCTION "app_private"."assign_scm_sales_quotation_line_numbers"() OWNER TO "postgres";

--

--
-- Name: attempt_workflow_business_callback("uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."attempt_workflow_business_callback"("p_outbox_id" "uuid", "p_worker_name" "text" DEFAULT 'workflow-inline'::"text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.wf_business_callback_outbox;
  v_attempt_no integer;
  v_started_at timestamptz := clock_timestamp();
  v_error_code text;
  v_error_message text;
begin
  select *
  into v_event
  from public.wf_business_callback_outbox o
  where o.id = p_outbox_id
  for update;

  if not found then
    raise exception '审批业务回调事件不存在';
  end if;

  if v_event.status = 'succeeded' then
    return 'succeeded';
  end if;

  if v_event.status = 'dead_letter' then
    return 'dead_letter';
  end if;

  if exists (
    select 1
    from public.wf_business_callback_outbox earlier
    where earlier.instance_id = v_event.instance_id
      and earlier.event_no < v_event.event_no
      and earlier.status <> 'succeeded'
  ) then
    return 'blocked_by_predecessor';
  end if;

  select coalesce(max(a.attempt_no), 0) + 1
  into v_attempt_no
  from public.wf_business_callback_attempt a
  where a.outbox_id = v_event.id;

  update public.wf_business_callback_outbox
  set status = 'processing',
      attempt_count = attempt_count + 1,
      locked_at = now(),
      locked_by = coalesce(nullif(btrim(p_worker_name), ''), 'workflow-worker'),
      last_error_code = null,
      last_error = null
  where id = v_event.id
  returning * into v_event;

  begin
    perform app_private.execute_workflow_business_callback(
      v_event.business_type,
      v_event.business_id,
      v_event.target_status,
      v_event.actor_name,
      v_event.callback_comment
    );

    insert into public.wf_business_callback_attempt(
      outbox_id, attempt_no, outcome, worker_name, duration_ms
    ) values (
      v_event.id,
      v_attempt_no,
      'succeeded',
      v_event.locked_by,
      greatest(0, extract(milliseconds from clock_timestamp() - v_started_at)::integer)
    );

    update public.wf_business_callback_outbox
    set status = 'succeeded',
        processed_at = now(),
        next_attempt_at = now(),
        locked_at = null,
        locked_by = null,
        last_error_code = null,
        last_error = null
    where id = v_event.id;

    return 'succeeded';
  exception
    when others then
      get stacked diagnostics
        v_error_code = returned_sqlstate,
        v_error_message = message_text;

      insert into public.wf_business_callback_attempt(
        outbox_id, attempt_no, outcome, worker_name,
        error_code, error_message, duration_ms
      ) values (
        v_event.id,
        v_attempt_no,
        'failed',
        v_event.locked_by,
        v_error_code,
        left(v_error_message, 2000),
        greatest(0, extract(milliseconds from clock_timestamp() - v_started_at)::integer)
      );

      update public.wf_business_callback_outbox
      set status = case
            when v_event.attempt_count >= v_event.max_attempts then 'dead_letter'
            else 'retry_wait'
          end,
          next_attempt_at = case
            when v_event.attempt_count >= v_event.max_attempts then now()
            else now() + make_interval(
              secs => least(3600, 60 * power(2, least(v_event.attempt_count - 1, 6))::integer)
            )
          end,
          locked_at = null,
          locked_by = null,
          last_error_code = v_error_code,
          last_error = left(v_error_message, 2000)
      where id = v_event.id;

      return case
        when v_event.attempt_count >= v_event.max_attempts then 'dead_letter'
        else 'retry_wait'
      end;
  end;
end;
$$;


ALTER FUNCTION "app_private"."attempt_workflow_business_callback"("p_outbox_id" "uuid", "p_worker_name" "text") OWNER TO "postgres";

