--
-- Name: mdm_process_route_prepare(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."mdm_process_route_prepare"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare v_next integer;v_unit uuid;begin
 if new.code is null or btrim(new.code)='' then perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text||':mdm_process_route',0));select coalesce(max(substring(code from '[0-9]+$')::integer),0)+1 into v_next from public.mdm_process_route where tenant_id=new.tenant_id and code~'^PR[0-9]+$';new.code:='PR'||lpad(v_next::text,4,'0');end if;
 if new.production_unit_id is null then select production_unit_id into v_unit from public.mdm_material where id=new.material_id and tenant_id=new.tenant_id;new.production_unit_id:=v_unit;end if;
 if new.group_id is not null and not exists(select 1 from public.mdm_master_group g where g.id=new.group_id and g.tenant_id=new.tenant_id and g.domain='process-route') then raise exception '工艺路线分组无效' using errcode='23503';end if;return new;end$_$;


