    AS $$
begin
 if nullif(btrim(new.code_prefix),'') is null then new.code_prefix:=btrim(new.category_code);
 elsif tg_op='UPDATE' and btrim(old.code_prefix)=btrim(old.category_code)
   and new.code_prefix is not distinct from old.code_prefix
   and new.category_code is distinct from old.category_code then new.code_prefix:=btrim(new.category_code);
 else new.code_prefix:=btrim(new.code_prefix); end if;
 return new;
