--

--
-- Name: next_document_number("text", "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."next_document_number"("p_rule_key" "text", "p_tenant_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_rule public.sys_document_number_rule;
  v_now timestamptz := clock_timestamp();
  v_period_key text;
  v_sequence bigint;
  v_width integer;
  v_result text;
begin
  if p_tenant_id is null then
    raise exception '生成编号时缺少租户';
  end if;
  if auth.uid() is not null
     and not app_private.is_platform_super()
     and p_tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权为其他租户生成编号';
  end if;

  select * into v_rule
  from public.sys_document_number_rule
  where tenant_id = p_tenant_id and rule_key = p_rule_key and enabled;
  if not found then
    raise exception '未找到已启用的编号规则：%', p_rule_key;
  end if;
  if not v_rule.auto_enabled then
    raise exception '编号规则 % 已切换为手工填写', v_rule.rule_name;
  end if;

  v_period_key := app_private.document_number_period_key(
    v_rule.reset_cycle, v_now, v_rule.timezone
  );
  insert into public.sys_document_number_counter (
    rule_id, tenant_id, rule_version, period_key, current_value, create_by, update_by
  ) values (
    v_rule.id, p_tenant_id, v_rule.rule_version, v_period_key, v_rule.sequence_start,
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine'),
    coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  )
  on conflict (rule_id, tenant_id, rule_version, period_key)
  do update set
    current_value = public.sys_document_number_counter.current_value + 1,
    update_time = now(),
    update_by = coalesce(nullif(auth.jwt() ->> 'email', ''), 'number-engine')
  returning current_value into v_sequence;

  v_width := substring(v_rule.template from '\{SEQ:([1-9][0-9]?)\}')::integer;
  if length(v_sequence::text) > v_width then
    raise exception '编号规则 % 的 % 位流水号已用尽，请调整模板', v_rule.rule_name, v_width;
  end if;

  v_result := v_rule.template;
  v_result := replace(v_result, '{YYYYMMDD}', to_char(v_now at time zone v_rule.timezone, 'YYYYMMDD'));
  v_result := replace(v_result, '{YYYYMM}', to_char(v_now at time zone v_rule.timezone, 'YYYYMM'));
  v_result := replace(v_result, '{YYMM}', to_char(v_now at time zone v_rule.timezone, 'YYMM'));
  v_result := replace(v_result, '{YYYY}', to_char(v_now at time zone v_rule.timezone, 'YYYY'));
  v_result := replace(v_result, '{YY}', to_char(v_now at time zone v_rule.timezone, 'YY'));
  v_result := replace(v_result, '{MM}', to_char(v_now at time zone v_rule.timezone, 'MM'));
  v_result := replace(v_result, '{DD}', to_char(v_now at time zone v_rule.timezone, 'DD'));
  return regexp_replace(v_result, '\{SEQ:[1-9][0-9]?\}', lpad(v_sequence::text, v_width, '0'));
end;
$$;


ALTER FUNCTION "app_private"."next_document_number"("p_rule_key" "text", "p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: next_fms_voucher_no("uuid", "uuid", smallint, smallint, "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."next_fms_voucher_no"("p_tenant_id" "uuid", "p_account_set_id" "uuid", "p_fiscal_year" smallint, "p_period_no" smallint, "p_voucher_type" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_sequence bigint;
  v_prefix text;
begin
  insert into public.fms_voucher_number_counter (
    tenant_id, account_set_id, fiscal_year, period_no, voucher_type, current_value
  ) values (p_tenant_id, p_account_set_id, p_fiscal_year, p_period_no, p_voucher_type, 1)
  on conflict (account_set_id, fiscal_year, period_no, voucher_type)
  do update set current_value = public.fms_voucher_number_counter.current_value + 1
  returning current_value into v_sequence;

  v_prefix := case p_voucher_type
    when 'receipt' then '收'
    when 'payment' then '付'
    when 'transfer' then '转'
    when 'adjustment' then '调'
    when 'closing' then '结'
    when 'reversal' then '冲'
    else '记'
  end;
  return format('%s-%s%s-%s', v_prefix, p_fiscal_year, lpad(p_period_no::text, 2, '0'), lpad(v_sequence::text, 6, '0'));
end;
$$;


ALTER FUNCTION "app_private"."next_fms_voucher_no"("p_tenant_id" "uuid", "p_account_set_id" "uuid", "p_fiscal_year" smallint, "p_period_no" smallint, "p_voucher_type" "text") OWNER TO "postgres";

--

--
-- Name: normalize_mdm_document_type(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."normalize_mdm_document_type"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_menu_type text;
begin
  if tg_op='UPDATE' and new.tenant_id is distinct from old.tenant_id then
    raise exception '单据类型所属租户不可修改' using errcode='22023';
  end if;
  new.document_type_code := upper(btrim(new.document_type_code));
  new.document_type_name := btrim(new.document_type_name);
  new.remark := btrim(coalesce(new.remark,''));
  new.text_color := upper(btrim(coalesce(new.text_color,'')));
  new.tag_style := lower(btrim(coalesce(new.tag_style,'')));

  select menu.type into v_menu_type from public.sys_menu menu where menu.id=new.menu_id;
  if v_menu_type is distinct from 'menu' then
    raise exception '单据类型必须归属到具体菜单功能' using errcode='22023';
  end if;
  if new.is_default and not new.enabled then
    raise exception '默认单据类型必须保持启用' using errcode='23514';
  end if;
  if new.is_default then
    update public.mdm_document_type sibling
    set is_default=false
    where sibling.tenant_id=new.tenant_id
      and sibling.menu_id=new.menu_id
      and sibling.id is distinct from new.id
      and sibling.is_default;
  end if;
  return new;
end
$$;


ALTER FUNCTION "app_private"."normalize_mdm_document_type"() OWNER TO "postgres";

