--
-- Name: mdm_supplier; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."mdm_supplier" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "supplier_name" character varying(100) NOT NULL,
    "contact_person" character varying(50),
    "contact_phone" character varying(20),
    "region" character varying(100),
    "address_detail" character varying(200),
    "remark" character varying(500),
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "created_by_user_id" "uuid" NOT NULL,
    "supplier_code" "text" DEFAULT ('SUP-'::"text" || "upper"("left"("replace"(("gen_random_uuid"())::"text", '-'::"text", ''::"text"), 12))) NOT NULL,
    "supplier_category" "text" DEFAULT 'material_supplier'::"text" NOT NULL,
    "supplier_group" "text",
    "supplier_type" "text" DEFAULT 'general'::"text" NOT NULL,
    "enterprise_nature" "text",
    "industry" "text",
    "region_adcode" "text",
    "longitude" numeric(11,7),
    "latitude" numeric(10,7),
    "coordinate_system" "text" DEFAULT 'gcj02'::"text" NOT NULL,
    "group_id" "uuid",
    CONSTRAINT "vehicle_supplier_address_length" CHECK ((("address_detail" IS NULL) OR ("char_length"(("address_detail")::"text") <= 300))),
    CONSTRAINT "vehicle_supplier_category_length" CHECK (("char_length"("supplier_category") <= 40)),
    CONSTRAINT "vehicle_supplier_code_length" CHECK (("char_length"("supplier_code") <= 40)),
    CONSTRAINT "vehicle_supplier_code_not_blank" CHECK (("btrim"("supplier_code") <> ''::"text")),
    CONSTRAINT "vehicle_supplier_contact_person_length" CHECK ((("contact_person" IS NULL) OR ("char_length"(("contact_person")::"text") <= 50))),
    CONSTRAINT "vehicle_supplier_contact_phone_length" CHECK ((("contact_phone" IS NULL) OR ("char_length"(("contact_phone")::"text") <= 30))),
    CONSTRAINT "vehicle_supplier_coordinate_pair_check" CHECK (((("longitude" IS NULL) AND ("latitude" IS NULL)) OR (("longitude" IS NOT NULL) AND ("latitude" IS NOT NULL)))),
    CONSTRAINT "vehicle_supplier_coordinate_system_check" CHECK (("coordinate_system" = ANY (ARRAY['gcj02'::"text", 'wgs84'::"text", 'bd09'::"text"]))),
    CONSTRAINT "vehicle_supplier_enterprise_nature_length" CHECK ((("enterprise_nature" IS NULL) OR ("char_length"("enterprise_nature") <= 40))),
    CONSTRAINT "vehicle_supplier_group_length" CHECK ((("supplier_group" IS NULL) OR ("char_length"("supplier_group") <= 80))),
    CONSTRAINT "vehicle_supplier_industry_length" CHECK ((("industry" IS NULL) OR ("char_length"("industry") <= 40))),
    CONSTRAINT "vehicle_supplier_latitude_range" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "vehicle_supplier_longitude_range" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "vehicle_supplier_name_length" CHECK (("char_length"(("supplier_name")::"text") <= 120)),
    CONSTRAINT "vehicle_supplier_remark_length" CHECK ((("remark" IS NULL) OR ("char_length"(("remark")::"text") <= 500))),
    CONSTRAINT "vehicle_supplier_type_length" CHECK (("char_length"("supplier_type") <= 40))
);


ALTER TABLE "public"."mdm_supplier" OWNER TO "postgres";

