--
-- Name: notification_target_tenant("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."notification_target_tenant"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant uuid := app_private.current_user_tenant_id();
begin
  if app_private.is_platform_super() then
    if p_tenant_id is null or not exists (select 1 from public.sys_tenant where id = p_tenant_id) then
      raise exception '请选择有效租户';
    end if;
    return p_tenant_id;
  end if;
  if v_current_tenant is null or (p_tenant_id is not null and p_tenant_id <> v_current_tenant) then
    raise exception '无权访问其他租户的提醒配置' using errcode = '42501';
  end if;
  return v_current_tenant;
end;
$$;


ALTER FUNCTION "app_private"."notification_target_tenant"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: permission_access_rank("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."permission_access_rank"("p_access" "text") RETURNS integer
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_access
    when 'edit' then 3
    when 'read' then 2
    when 'masked' then 1
    else 0
  end;
$$;


ALTER FUNCTION "app_private"."permission_access_rank"("p_access" "text") OWNER TO "postgres";

