--

--
-- Name: process_notification_reminders_for_tenant("uuid", integer); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."process_notification_reminders_for_tenant"("p_tenant_id" "uuid", "p_limit" integer DEFAULT 500) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_today date := (now() at time zone 'Asia/Shanghai')::date;
  v_limit integer := least(greatest(coalesce(p_limit, 500), 1), 2000);
  v_created_events integer := 0;
  v_created_deliveries integer := 0;
  v_delivered_in_app integer := 0;
  v_delivery record;
begin
  if p_tenant_id is null or not exists (select 1 from public.sys_tenant where id = p_tenant_id) then
    raise exception 'Tenant not found';
  end if;

  insert into public.sys_notification_event (
    tenant_id, subject_id, rule_id, occurrence_date, scheduled_at,
    title, content, severity, status, create_by, update_by
  )
  select
    subject.tenant_id, subject.id, rule_row.id,
    case when rule_row.repeat_every_days is null
      then (subject.due_at at time zone 'Asia/Shanghai')::date - rule_row.lead_days
      else v_today end,
    (case when rule_row.repeat_every_days is null
      then (subject.due_at at time zone 'Asia/Shanghai')::date - rule_row.lead_days
      else v_today end + make_time(rule_row.send_hour, 0, 0)) at time zone 'Asia/Shanghai',
    subject.subject_title,
    case
      when (subject.due_at at time zone 'Asia/Shanghai')::date < v_today
        then subject.subject_title || '，已到期 ' || (v_today - (subject.due_at at time zone 'Asia/Shanghai')::date) || ' 天，请尽快处理。'
      when (subject.due_at at time zone 'Asia/Shanghai')::date = v_today
        then subject.subject_title || '，今天到期，请及时处理。'
      else subject.subject_title || '，还有 ' || ((subject.due_at at time zone 'Asia/Shanghai')::date - v_today) || ' 天到期，请提前处理。'
    end,
    case when (subject.due_at at time zone 'Asia/Shanghai')::date <= v_today then 'danger' else 'warning' end,
    'pending', 'system-reminder', 'system-reminder'
  from public.sys_notification_subject subject
  join public.sys_notification_rule rule_row
    on rule_row.tenant_id = subject.tenant_id
   and rule_row.scenario_id = subject.scenario_id
   and rule_row.enabled is true
  join public.sys_tenant tenant_row on tenant_row.id = subject.tenant_id and tenant_row.status = '1'
  where subject.tenant_id = p_tenant_id
    and subject.status = 'active'
    and v_today >= (subject.due_at at time zone 'Asia/Shanghai')::date - rule_row.lead_days
    and v_today <= (subject.due_at at time zone 'Asia/Shanghai')::date
    and (
      rule_row.repeat_every_days is null
      or mod(
        v_today - ((subject.due_at at time zone 'Asia/Shanghai')::date - rule_row.lead_days),
        rule_row.repeat_every_days
      ) = 0
    )
  on conflict (subject_id, rule_id, occurrence_date) do nothing;
  get diagnostics v_created_events = row_count;

  insert into public.sys_notification_delivery (
    tenant_id, event_id, recipient_user_id, channel_code, title, content,
    route_path, route_query, status, create_by, update_by
  )
  select distinct
    event_row.tenant_id, event_row.id, recipient.id, channel.channel_code,
    event_row.title, event_row.content, subject.route_path, subject.route_query,
    'pending', 'system-reminder', 'system-reminder'
  from public.sys_notification_event event_row
  join public.sys_notification_subject subject
    on subject.id = event_row.subject_id and subject.tenant_id = event_row.tenant_id
  join public.sys_notification_rule rule_row
    on rule_row.id = event_row.rule_id and rule_row.tenant_id = event_row.tenant_id
  join public.sys_notification_channel_config channel
    on channel.tenant_id = event_row.tenant_id
   and channel.channel_code = any(rule_row.channels)
   and channel.enabled is true
  join lateral (
    select user_row.id
    from public.sys_user user_row
    where user_row.tenant_id = event_row.tenant_id
      and user_row.status = '1'
      and user_row.deleted_at is null
      and (
        (rule_row.recipient_strategy = 'owner_then_roles' and user_row.id = subject.owner_user_id)
        or exists (
          select 1 from public.sys_role role_row
          where role_row.tenant_id = user_row.tenant_id
            and role_row.enabled is true
            and role_row.role_code = any(coalesce(user_row.user_roles, array[]::text[]))
            and role_row.role_code = any(rule_row.recipient_role_codes)
        )
      )
  ) recipient on true
  where event_row.tenant_id = p_tenant_id
    and event_row.status in ('pending', 'failed')
    and event_row.scheduled_at <= now()
  on conflict (event_id, recipient_user_id, channel_code) do nothing;
  get diagnostics v_created_deliveries = row_count;

  for v_delivery in
    select delivery.*, subject.business_type, subject.business_id
    from public.sys_notification_delivery delivery
    left join public.sys_notification_event event_row on event_row.id = delivery.event_id
    left join public.sys_notification_subject subject on subject.id = event_row.subject_id
    where delivery.tenant_id = p_tenant_id
      and delivery.channel_code = 'in_app'
      and delivery.status in ('pending', 'failed')
      and (delivery.next_retry_at is null or delivery.next_retry_at <= now())
    order by delivery.create_time
    for update of delivery skip locked
    limit v_limit
  loop
    begin
      update public.sys_notification_delivery
      set status = 'processing', attempt_count = attempt_count + 1, update_by = 'system-reminder'
      where id = v_delivery.id;
      perform app_private.enqueue_user_notification(
        v_delivery.recipient_user_id, v_delivery.tenant_id, 'message',
        v_delivery.title, v_delivery.content, 'warning', 'notification_reminder_delivery',
        v_delivery.id, v_delivery.business_type, v_delivery.business_id, null,
        v_delivery.route_path, v_delivery.route_query
      );
      update public.sys_notification_delivery
      set status = 'delivered', delivered_at = now(), next_retry_at = null,
          error_message = null, update_by = 'system-reminder'
      where id = v_delivery.id;
      v_delivered_in_app := v_delivered_in_app + 1;
    exception when others then
      update public.sys_notification_delivery
      set status = 'failed', next_retry_at = now() + interval '15 minutes',
          error_message = left(sqlerrm, 1000), update_by = 'system-reminder'
      where id = v_delivery.id;
    end;
  end loop;

  update public.sys_notification_event event_row
  set status = case
        when exists (select 1 from public.sys_notification_delivery d where d.event_id = event_row.id and d.status in ('pending','processing','failed')) then 'queued'
        when exists (select 1 from public.sys_notification_delivery d where d.event_id = event_row.id and d.status = 'delivered') then 'delivered'
        else 'failed'
      end,
      update_by = 'system-reminder'
  where event_row.tenant_id = p_tenant_id
    and event_row.status in ('pending', 'queued', 'failed')
    and exists (select 1 from public.sys_notification_delivery d where d.event_id = event_row.id);

  return jsonb_build_object(
    'createdEventCount', v_created_events,
    'createdDeliveryCount', v_created_deliveries,
    'deliveredInAppCount', v_delivered_in_app
  );
end;
$$;


ALTER FUNCTION "app_private"."process_notification_reminders_for_tenant"("p_tenant_id" "uuid", "p_limit" integer) OWNER TO "postgres";

--

--
-- Name: publish_workflow_definition("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."publish_workflow_definition"("p_definition_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_target_tenant_id uuid;
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
  v_version public.wf_version;
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程发布权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    and (v_is_platform_super or d.tenant_id = v_current_tenant_id)
  for update;

  if not found then
    raise exception '流程不存在或无权发布';
  end if;

  v_target_tenant_id := v_definition.tenant_id;
  perform pg_advisory_xact_lock(
    hashtextextended(v_target_tenant_id::text || ':' || v_definition.business_type, 81173)
  );

  if exists (
    select 1
    from public.wf_definition d
    where d.tenant_id = v_target_tenant_id
      and d.business_type = v_definition.business_type
      and d.status = 'published'
      and d.id <> v_definition.id
  ) then
    raise exception '该业务类型已有启用流程，请先停用后再发布';
  end if;

  select *
  into v_version
  from public.wf_version v
  where v.definition_id = v_definition.id
    and v.status = 'draft'
  for update;

  if not found then
    raise exception '没有可发布的草稿版本';
  end if;

  perform app_private.validate_workflow_config(v_version.config);

  update public.wf_version
  set status = 'retired', update_by = v_actor
  where definition_id = v_definition.id
    and status = 'published';

  update public.wf_version
  set status = 'published',
      published_at = now(),
      published_by = v_actor,
      update_by = v_actor
  where id = v_version.id
  returning * into v_version;

  update public.wf_definition
  set status = 'published',
      current_version_id = v_version.id,
      published_at = now(),
      published_by = v_actor,
      update_by = v_actor
  where id = v_definition.id;

  return jsonb_build_object(
    'definitionId', v_definition.id,
    'versionId', v_version.id,
    'versionNo', v_version.version_no,
    'tenantId', v_target_tenant_id
  );
end;
$$;


ALTER FUNCTION "app_private"."publish_workflow_definition"("p_definition_id" "uuid") OWNER TO "postgres";

--

--
-- Name: refresh_fms_voucher_totals("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."refresh_fms_voucher_totals"("p_voucher_id" "uuid") RETURNS "void"
    LANGUAGE "sql"
    SET "search_path" TO ''
    AS $$
  update public.fms_voucher v
  set total_debit = totals.debit,
      total_credit = totals.credit,
      line_count = totals.line_count
  from (
    select coalesce(sum(line.debit_amount), 0)::numeric(20, 2) as debit,
      coalesce(sum(line.credit_amount), 0)::numeric(20, 2) as credit,
      count(*)::integer as line_count
    from public.fms_voucher_line line
    where line.voucher_id = p_voucher_id
  ) totals
  where v.id = p_voucher_id
$$;


ALTER FUNCTION "app_private"."refresh_fms_voucher_totals"("p_voucher_id" "uuid") OWNER TO "postgres";

--

--
-- Name: resolve_field_access("text", "text", "uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."resolve_field_access"("p_resource_key" "text", "p_field_key" "text", "p_record_owner_id" "uuid" DEFAULT NULL::"uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_user_id uuid := app_private.current_app_user_id();
  v_field public.sys_permission_field%rowtype;
  v_user_access text;
  v_role_access text;
begin
  if (select auth.uid()) is null or v_tenant_id is null or v_user_id is null then
    return 'hidden';
  end if;

  if app_private.is_platform_super() then
    return 'edit';
  end if;

  select field_row.*
    into v_field
  from public.sys_permission_resource resource_row
  join public.sys_permission_field field_row
    on field_row.resource_id = resource_row.id
   and field_row.tenant_id = resource_row.tenant_id
  where resource_row.tenant_id = v_tenant_id
    and resource_row.resource_key = p_resource_key
    and resource_row.enabled is true
    and field_row.field_key = p_field_key
    and field_row.sensitive is true
    and field_row.enabled is true;

  if not found then
    return 'hidden';
  end if;

  if v_field.owner_override_enabled
     and p_record_owner_id is not null
     and p_record_owner_id = v_user_id then
    return 'edit';
  end if;

  select permission_row.access_level
    into v_user_access
  from public.sys_user_field_permission permission_row
  where permission_row.tenant_id = v_tenant_id
    and permission_row.user_id = v_user_id
    and permission_row.resource_id = v_field.resource_id
    and permission_row.field_id = v_field.id;

  if found then
    return v_user_access;
  end if;

  select case max(app_private.permission_access_rank(permission_row.access_level))
    when 3 then 'edit'
    when 2 then 'read'
    when 1 then 'masked'
    when 0 then 'hidden'
    else null
  end
    into v_role_access
  from public.sys_user current_user_row
  join public.sys_role role_row
    on role_row.tenant_id = current_user_row.tenant_id
   and role_row.enabled is true
   and role_row.role_code = any(coalesce(current_user_row.user_roles, array[]::text[]))
  join public.sys_role_field_permission permission_row
    on permission_row.tenant_id = role_row.tenant_id
   and permission_row.role_id = role_row.id
   and permission_row.resource_id = v_field.resource_id
   and permission_row.field_id = v_field.id
  where current_user_row.id = v_user_id
    and current_user_row.tenant_id = v_tenant_id
    and current_user_row.status = '1'
    and current_user_row.deleted_at is null;

  return coalesce(v_role_access, v_field.default_access, 'hidden');
end;
$$;


ALTER FUNCTION "app_private"."resolve_field_access"("p_resource_key" "text", "p_field_key" "text", "p_record_owner_id" "uuid") OWNER TO "postgres";

--

--
-- Name: resolve_fms_posting_account_set("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."resolve_fms_posting_account_set"("p_tenant_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_id uuid;
  v_count integer;
begin
  select id into v_id
  from public.fms_account_set
  where tenant_id = p_tenant_id
    and status = 'active'
    and is_default
  order by enabled_on, id
  limit 1;

  if v_id is not null then
    return v_id;
  end if;

  select count(*)::integer into v_count
  from public.fms_account_set
  where tenant_id = p_tenant_id
    and status = 'active';

  if v_count = 1 then
    select id into v_id
    from public.fms_account_set
    where tenant_id = p_tenant_id
      and status = 'active'
    order by enabled_on, id
    limit 1;
    return v_id;
  end if;

  return null;
end;
$$;


ALTER FUNCTION "app_private"."resolve_fms_posting_account_set"("p_tenant_id" "uuid") OWNER TO "postgres";

--

--
-- Name: retry_workflow_business_callback("uuid"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."retry_workflow_business_callback"("p_outbox_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result text;
begin
  if (select auth.uid()) is null or not (select app_private.is_platform_super()) then
    raise exception '当前账号没有审批回调补偿权限' using errcode = '42501';
  end if;

  update public.wf_business_callback_outbox
  set status = 'pending',
      attempt_count = 0,
      next_attempt_at = now(),
      processed_at = null,
      locked_at = null,
      locked_by = null,
      manual_retry_count = manual_retry_count + 1,
      last_error_code = null,
      last_error = null
  where id = p_outbox_id
    and status in ('retry_wait', 'dead_letter');

  if not found then
    raise exception '仅失败重试中或死信状态的回调允许人工补偿';
  end if;

  v_result := app_private.attempt_workflow_business_callback(
    p_outbox_id,
    'workflow-manual:' || auth.uid()::text
  );

  return jsonb_build_object('id', p_outbox_id, 'status', v_result);
end;
$$;


ALTER FUNCTION "app_private"."retry_workflow_business_callback"("p_outbox_id" "uuid") OWNER TO "postgres";

--

--
-- Name: revoke_workflow_delegation("uuid", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."revoke_workflow_delegation"("p_delegation_id" "uuid", "p_reason" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_user_id uuid := (select app_private.current_app_user_id());
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_reason text := btrim(coalesce(p_reason, ''));
  v_delegation public.wf_delegation;
  v_actor_name text;
  v_delegator_name text;
  v_task record;
begin
  if (select auth.uid()) is null or v_user_id is null then
    raise exception '当前登录用户未绑定业务账号';
  end if;
  if char_length(v_reason) not between 4 and 300 then
    raise exception '撤销原因需填写 4 至 300 个字符';
  end if;

  select * into v_delegation
  from public.wf_delegation
  where id = p_delegation_id
    and (v_is_platform_super or tenant_id = v_tenant_id)
  for update;

  if not found or (not v_is_platform_super and v_delegation.delegator_user_id <> v_user_id) then
    raise exception '委托不存在或无权撤销' using errcode = '42501';
  end if;
  if v_delegation.revoked_at is not null then return v_delegation.id; end if;

  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_actor_name from public.sys_user where id = v_user_id;
  select coalesce(nullif(nick_name,''), nullif(user_name,''), user_email, id::text)
  into v_delegator_name from public.sys_user where id = v_delegation.delegator_user_id;

  update public.wf_delegation
  set revoked_at = now(), revoked_by = v_user_id, revoke_reason = v_reason
  where id = v_delegation.id;

  perform 1
  from public.wf_instance instance
  where instance.id in (
    select task.instance_id from public.wf_task task
    where task.delegation_id = v_delegation.id
      and task.status = 'pending'
  )
  order by instance.id
  for update;

  for v_task in
    select task.*, instance.business_type, instance.business_id, instance.business_title
    from public.wf_task task
    join public.wf_instance instance on instance.id = task.instance_id
    join public.sys_user original_user on original_user.id = task.original_assignee_user_id
    where task.delegation_id = v_delegation.id
      and task.status = 'pending'
      and original_user.status = '1'
    order by task.id
    for update of task
  loop
    update public.wf_task
    set assignee_user_id = v_task.original_assignee_user_id,
        assignee_name_snapshot = v_task.original_assignee_name_snapshot,
        assignment_source = 'direct', delegation_id = null,
        last_assigned_by = v_user_id, assignment_reason = v_reason
    where id = v_task.id;

    insert into public.wf_action(
      instance_id, task_id, node_key, node_name, action,
      actor_user_id, actor_name_snapshot, comment, metadata, tenant_id
    ) values (
      v_task.instance_id, v_task.id, v_task.node_key, v_task.node_name, 'delegation_revoke',
      v_user_id, v_actor_name, v_reason,
      jsonb_build_object(
        'delegationId', v_delegation.id,
        'fromUserId', v_delegation.delegate_user_id,
        'toUserId', v_task.original_assignee_user_id,
        'toUserName', v_task.original_assignee_name_snapshot
      ), v_delegation.tenant_id
    );

    perform app_private.enqueue_user_notification(
      v_task.original_assignee_user_id, v_delegation.tenant_id, 'todo', '委托已撤销，待办已收回',
      '“' || v_task.business_title || '”已恢复由你审批：' || v_reason,
      'info', 'workflow_delegation_revoke', v_task.id,
      v_task.business_type, v_task.business_id, v_task.instance_id,
      '/workflow/workbench', jsonb_build_object('tab','pending','instanceId',v_task.instance_id)
    );
  end loop;

  return v_delegation.id;
end;
$$;


ALTER FUNCTION "app_private"."revoke_workflow_delegation"("p_delegation_id" "uuid", "p_reason" "text") OWNER TO "postgres";

--

--
-- Name: save_workflow_definition("jsonb"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."save_workflow_definition"("p_definition" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_target_tenant_id uuid;
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
  v_version public.wf_version;
  v_definition_id uuid;
  v_config jsonb := coalesce(p_definition -> 'config', '{"nodes":[]}'::jsonb);
  v_actor text;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程配置权限' using errcode = '42501';
  end if;

  perform app_private.validate_workflow_config(v_config);
  v_actor := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);

  begin
    v_definition_id := nullif(p_definition ->> 'id', '')::uuid;
  exception
    when invalid_text_representation then
      raise exception '流程 ID 格式不正确';
  end;

  if v_definition_id is null then
    begin
      v_target_tenant_id := nullif(p_definition ->> 'tenantId', '')::uuid;
    exception
      when invalid_text_representation then
        raise exception '所属租户格式不正确';
    end;

    if not v_is_platform_super then
      v_target_tenant_id := v_current_tenant_id;
    else
      v_target_tenant_id := coalesce(v_target_tenant_id, v_current_tenant_id);
    end if;

    if not exists (
      select 1
      from public.sys_tenant t
      where t.id = v_target_tenant_id
        and t.status = '1'
    ) then
      raise exception '所属租户不存在或已停用';
    end if;

    insert into public.wf_definition(
      code,
      name,
      business_type,
      description,
      tenant_id,
      create_by,
      update_by
    )
    values (
      btrim(p_definition ->> 'code'),
      btrim(p_definition ->> 'name'),
      btrim(p_definition ->> 'businessType'),
      nullif(btrim(coalesce(p_definition ->> 'description', '')), ''),
      v_target_tenant_id,
      v_actor,
      v_actor
    )
    returning * into v_definition;

    insert into public.wf_version(
      definition_id,
      version_no,
      config,
      change_note,
      tenant_id,
      create_by,
      update_by
    )
    values (
      v_definition.id,
      1,
      v_config,
      nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
      v_target_tenant_id,
      v_actor,
      v_actor
    )
    returning * into v_version;
  else
    select *
    into v_definition
    from public.wf_definition d
    where d.id = v_definition_id
      and (v_is_platform_super or d.tenant_id = v_current_tenant_id)
    for update;

    if not found then
      raise exception '流程不存在或无权编辑';
    end if;

    v_target_tenant_id := v_definition.tenant_id;

    if v_definition.current_version_id is not null and (
      v_definition.code <> btrim(p_definition ->> 'code')
      or v_definition.business_type <> btrim(p_definition ->> 'businessType')
    ) then
      raise exception '流程发布后不可修改流程编码和业务类型';
    end if;

    update public.wf_definition
    set name = btrim(p_definition ->> 'name'),
        description = nullif(btrim(coalesce(p_definition ->> 'description', '')), ''),
        update_by = v_actor
    where id = v_definition.id
    returning * into v_definition;

    select *
    into v_version
    from public.wf_version v
    where v.definition_id = v_definition.id
      and v.status = 'draft'
    for update;

    if found then
      update public.wf_version
      set config = v_config,
          change_note = nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
          update_by = v_actor
      where id = v_version.id
      returning * into v_version;
    else
      insert into public.wf_version(
        definition_id,
        version_no,
        config,
        change_note,
        tenant_id,
        create_by,
        update_by
      )
      select v_definition.id,
             coalesce(max(v.version_no), 0) + 1,
             v_config,
             nullif(btrim(coalesce(p_definition ->> 'changeNote', '')), ''),
             v_target_tenant_id,
             v_actor,
             v_actor
      from public.wf_version v
      where v.definition_id = v_definition.id
      returning * into v_version;
    end if;
  end if;

  return jsonb_build_object(
    'definitionId', v_definition.id,
    'versionId', v_version.id,
    'versionNo', v_version.version_no,
    'tenantId', v_definition.tenant_id
  );
end;
$$;


ALTER FUNCTION "app_private"."save_workflow_definition"("p_definition" "jsonb") OWNER TO "postgres";

