--
-- Name: scm_purchase_permission_prefix("text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."scm_purchase_permission_prefix"("p_kind" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_kind
    when 'purchase_contract' then 'ScmPurchaseContract'
    when 'purchase_request' then 'ScmPurchaseRequest'
    when 'purchase_order' then 'ScmPurchaseOrder'
    when 'receipt_notice' then 'ScmReceiptNotice'
    else '' end
