--

--
-- Name: scm_quote_source_of_truth(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."scm_quote_source_of_truth"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_source public.scm_sales_document%rowtype; v_details jsonb;
begin
 if new.kind='sales_quotation' then
  v_details:=coalesce(new.details,'{}'::jsonb);
  if v_details->>'quotation_scene' not in ('standard','project') then
   raise exception '请选择标准产品或项目工程报价场景' using errcode='23514';
  end if;
  if v_details->>'quotation_scene'='standard' and new.project_id is null then
   raise exception '标准产品报价须关联已有项目' using errcode='23514';
  end if;
  if v_details->>'quotation_scene'='project' then
   if nullif(btrim(v_details->>'construction_no'),'') is null then raise exception '工程报价须填写施工号' using errcode='23514'; end if;
   if new.project_id is null and (not coalesce((v_details->>'auto_create_project')::boolean,false) or nullif(btrim(v_details->>'planned_project_name'),'') is null) then
    raise exception '工程报价须选择项目，或启用自动建项目并填写项目名称' using errcode='23514';
   end if;
   if (coalesce((v_details->>'auto_create_materials')::boolean,false) or coalesce((v_details->>'auto_build_bom')::boolean,false)) and
      (nullif(v_details->>'material_category_id','') is null or nullif(v_details->>'base_unit_id','') is null or nullif(v_details->>'material_code_rule_id','') is null) then
    raise exception '请完整配置工程物料分类、单位和编码规则' using errcode='23514';
   end if;
   if coalesce((v_details->>'auto_build_bom')::boolean,false) and not coalesce((v_details->>'auto_create_materials')::boolean,false) and
      exists(select 1 from jsonb_array_elements(new.lines) line where nullif(line->>'material_id','') is null) then
    raise exception '未编码工程子目须启用自动建物料才能搭建 BOM' using errcode='23514';
   end if;
   if nullif(v_details->>'material_category_id','') is not null and not exists(select 1 from public.mdm_material_category where id=(v_details->>'material_category_id')::uuid and tenant_id=new.tenant_id and status='enabled') then raise exception '工程物料分类与报价租户不一致或已停用' using errcode='23514'; end if;
   if nullif(v_details->>'base_unit_id','') is not null and not exists(select 1 from public.mdm_unit_of_measure where id=(v_details->>'base_unit_id')::uuid and tenant_id=new.tenant_id and status='enabled') then raise exception '工程基本单位与报价租户不一致或已停用' using errcode='23514'; end if;
   if nullif(v_details->>'material_code_rule_id','') is not null and not exists(select 1 from public.mdm_material_code_rule where id=(v_details->>'material_code_rule_id')::uuid and tenant_id=new.tenant_id and status='enabled') then raise exception '工程编码规则与报价租户不一致或已停用' using errcode='23514'; end if;
  end if;
  return new;
 end if;
 if new.kind<>'project_quotation' then return new; end if;
 if current_setting('app.scm_project_activation',true)=new.id::text then return new; end if;
 if tg_op='UPDATE' and old.status<>'created' then return new; end if;
 if tg_op='UPDATE' and new.source_id is distinct from old.source_id then
  raise exception '项目报价创建后不可更换来源销售报价' using errcode='23514';
 end if;
 if new.source_id is null then raise exception '项目报价必须选择来源销售报价单' using errcode='23514'; end if;
 select * into v_source from public.scm_sales_document where id=new.source_id and kind='sales_quotation' and tenant_id=new.tenant_id and status='effective' and app_private.tenant_in_current_read_scope(tenant_id) for share;
 if v_source.id is null or v_source.details->>'quotation_scene' is distinct from 'project' then raise exception '请选择已生效的工程销售报价单' using errcode='23514'; end if;
 new.project_id:=v_source.project_id;
 new.customer_id:=v_source.customer_id;
 new.currency:=v_source.currency;
 new.delivery_date:=v_source.delivery_date;
 new.details:=v_source.details;
 new.lines:=v_source.lines;
 new.fees:=v_source.fees;
 new.remark:=v_source.remark;
 return new;
end $$;


ALTER FUNCTION "app_private"."scm_quote_source_of_truth"() OWNER TO "postgres";

--

--
-- Name: scm_receipt_stock_quantity("uuid", "uuid", numeric); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."scm_receipt_stock_quantity"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_receipt_quantity" numeric) RETURNS numeric
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_material public.mdm_material%rowtype;
 v_purchase_factor numeric := 1;
 v_stock_factor numeric := 1;
begin
 select * into v_material from public.mdm_material
 where id=p_material_id and tenant_id=p_tenant_id;
 if not found or p_receipt_quantity<=0 then
   raise exception '物料不存在或收料数量无效' using errcode='23514';
 end if;
 if v_material.purchase_unit_id is distinct from v_material.base_unit_id then
   select (x->>'base_factor')::numeric / nullif((x->>'source_factor')::numeric,0)
   into v_purchase_factor
   from jsonb_array_elements(coalesce(v_material.unit_conversions,'[]'::jsonb)) x
   where x->>'source_unit_id'=v_material.purchase_unit_id::text limit 1;
 end if;
 if v_material.inventory_unit_id is distinct from v_material.base_unit_id then
   select (x->>'base_factor')::numeric / nullif((x->>'source_factor')::numeric,0)
   into v_stock_factor
   from jsonb_array_elements(coalesce(v_material.unit_conversions,'[]'::jsonb)) x
   where x->>'source_unit_id'=v_material.inventory_unit_id::text limit 1;
 end if;
 if v_purchase_factor is null or v_stock_factor is null
    or v_purchase_factor<=0 or v_stock_factor<=0 then
   raise exception '物料缺少有效的采购单位或库存单位换算关系' using errcode='23514';
 end if;
 return round(p_receipt_quantity*v_purchase_factor/v_stock_factor,3);
end $$;


ALTER FUNCTION "app_private"."scm_receipt_stock_quantity"("p_tenant_id" "uuid", "p_material_id" "uuid", "p_receipt_quantity" numeric) OWNER TO "postgres";

--

--
-- Name: search_platform_global_pending_workflow_tasks("text", "text", "uuid", integer, integer); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."search_platform_global_pending_workflow_tasks"("p_keyword" "text" DEFAULT NULL::"text", "p_business_type" "text" DEFAULT NULL::"text", "p_tenant_id" "uuid" DEFAULT NULL::"uuid", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from integer:=greatest(coalesce(p_from,0),0);
  v_limit integer:=least(greatest(coalesce(p_to,19)-greatest(coalesce(p_from,0),0)+1,1),100);
  v_keyword text:=nullif(btrim(coalesce(p_keyword,'')),'');
  v_result jsonb;
begin
  if (select auth.uid()) is null or not (select app_private.is_platform_super()) then
    raise exception '仅平台超级管理员可以查看全局待办' using errcode='42501';
  end if;
  with base as (
    select t.*,i.business_title,i.business_type,i.business_id,i.initiator_name_snapshot,
      i.definition_id,i.version_id,i.status instance_status,i.current_node_key,
      d.code definition_code,d.name definition_name,v.version_no,v.config,
      tenant.tenant_code,tenant.tenant_name
    from public.wf_task t
    join public.wf_instance i on i.id=t.instance_id
    join public.wf_definition d on d.id=i.definition_id
    join public.wf_version v on v.id=i.version_id
    join public.sys_tenant tenant on tenant.id=t.tenant_id
    where t.status='pending' and i.status='running' and i.current_node_key=t.node_key
      and (p_tenant_id is null or t.tenant_id=p_tenant_id)
      and (nullif(p_business_type,'') is null or i.business_type=p_business_type)
      and (v_keyword is null or i.business_title ilike '%'||v_keyword||'%'
        or i.business_id::text ilike '%'||v_keyword||'%'
        or i.initiator_name_snapshot ilike '%'||v_keyword||'%'
        or t.assignee_name_snapshot ilike '%'||v_keyword||'%'
        or tenant.tenant_name ilike '%'||v_keyword||'%' or d.name ilike '%'||v_keyword||'%')
  ), grouped as (
    select instance_id,node_key,min(id::text)::uuid representative_id,count(*)::integer assignee_count,
      count(*) filter(where status='pending')::integer pending_assignee_count,
      jsonb_agg(distinct assignee_name_snapshot order by assignee_name_snapshot) assignee_names,
      min(due_at) due_at,min(create_time) create_time,
      min(case when due_at is not null and due_at<now() then 0 else 1 end) urgency_order
    from base group by instance_id,node_key
  ), records as (
    select to_jsonb(b)-array['business_title','business_type','business_id','initiator_name_snapshot',
      'definition_id','version_id','instance_status','current_node_key','definition_code',
      'definition_name','version_no','config','tenant_code','tenant_name']
      ||jsonb_build_object(
        'assigneeCount',g.assignee_count,'pendingAssigneeCount',g.pending_assignee_count,
        'assigneeNames',g.assignee_names,
        'instance',jsonb_build_object('id',b.instance_id,'definitionId',b.definition_id,
          'versionId',b.version_id,'businessType',b.business_type,'businessId',b.business_id,
          'businessTitle',b.business_title,'initiatorNameSnapshot',b.initiator_name_snapshot,
          'status',b.instance_status,'currentNodeKey',b.current_node_key,
          'definition',jsonb_build_object('id',b.definition_id,'code',b.definition_code,
            'name',b.definition_name,'businessType',b.business_type),
          'version',jsonb_build_object('id',b.version_id,'versionNo',b.version_no,'config',b.config)),
        'tenant',jsonb_build_object('id',b.tenant_id,'tenantCode',b.tenant_code,'tenantName',b.tenant_name)
      ) record,g.urgency_order,g.due_at,g.create_time
    from grouped g join base b on b.id=g.representative_id
  ), page_rows as (
    select * from records order by urgency_order,due_at nulls last,create_time desc
    offset v_from limit v_limit
  )
  select jsonb_build_object(
    'records',coalesce((select jsonb_agg(record order by urgency_order,due_at nulls last,create_time desc) from page_rows),'[]'::jsonb),
    'total',(select count(*) from grouped),
    'taskTotal',(select coalesce(sum(assignee_count),0) from grouped)
  ) into v_result;
  return v_result;
end;$$;


ALTER FUNCTION "app_private"."search_platform_global_pending_workflow_tasks"("p_keyword" "text", "p_business_type" "text", "p_tenant_id" "uuid", "p_from" integer, "p_to" integer) OWNER TO "postgres";

--

--
-- Name: search_workflow_instances_for_monitor("text", "text", "text", "text", integer, integer); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."search_workflow_instances_for_monitor"("p_keyword" "text" DEFAULT NULL::"text", "p_business_type" "text" DEFAULT NULL::"text", "p_status" "text" DEFAULT NULL::"text", "p_sla_status" "text" DEFAULT NULL::"text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 19) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_from integer := greatest(coalesce(p_from, 0), 0);
  v_limit integer := least(greatest(coalesce(p_to, 19) - greatest(coalesce(p_from, 0), 0) + 1, 1), 100);
  v_result jsonb;
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_tenant_id uuid := (select app_private.current_user_tenant_id());
begin
  if (select auth.uid()) is null then
    raise exception '请先登录后查看审批监控' using errcode = '42501';
  end if;
  if not v_is_platform_super and v_tenant_id is null then
    raise exception '当前账号未关联有效租户' using errcode = '42501';
  end if;
  if nullif(p_status, '') is not null
     and p_status not in ('running', 'approved', 'rejected', 'withdrawn', 'cancelled') then
    raise exception '无效的流程状态';
  end if;
  if nullif(p_sla_status, '') is not null and p_sla_status not in ('normal', 'overdue') then
    raise exception '无效的时效状态';
  end if;

  with scoped as (
    select
      i as instance_record,
      d.name as definition_name,
      d.code as definition_code,
      v.version_no,
      coalesce(task_stats.pending_task_count, 0) as pending_task_count,
      task_stats.nearest_due_at,
      coalesce(task_stats.is_overdue, false) as is_overdue,
      round(
        (extract(epoch from (coalesce(i.finished_at, now()) - i.started_at)) / 3600)::numeric,
        1
      ) as duration_hours
    from public.wf_instance i
    join public.wf_definition d on d.id = i.definition_id
    join public.wf_version v on v.id = i.version_id
    left join lateral (
      select
        count(*)::integer as pending_task_count,
        min(t.due_at) as nearest_due_at,
        bool_or(t.due_at < now()) filter (where t.due_at is not null) as is_overdue
      from public.wf_task t
      where t.instance_id = i.id and t.status = 'pending'
    ) task_stats on true
    where v_is_platform_super or i.tenant_id = v_tenant_id
  ), filtered as (
    select
      to_jsonb(instance_record) || jsonb_build_object(
        'definition_name', definition_name,
        'definition_code', definition_code,
        'version_no', version_no,
        'pending_task_count', pending_task_count,
        'nearest_due_at', nearest_due_at,
        'is_overdue', is_overdue,
        'duration_hours', duration_hours
      ) as record,
      (instance_record).started_at as started_at
    from scoped
    where (
      nullif(btrim(coalesce(p_keyword, '')), '') is null
      or (instance_record).business_title ilike '%' || btrim(p_keyword) || '%'
      or (instance_record).business_id::text ilike '%' || btrim(p_keyword) || '%'
      or (instance_record).initiator_name_snapshot ilike '%' || btrim(p_keyword) || '%'
      or definition_name ilike '%' || btrim(p_keyword) || '%'
    )
      and (nullif(p_business_type, '') is null or (instance_record).business_type = p_business_type)
      and (nullif(p_status, '') is null or (instance_record).status = p_status)
      and (
        nullif(p_sla_status, '') is null
        or (p_sla_status = 'overdue' and is_overdue)
        or (p_sla_status = 'normal' and not is_overdue)
      )
  ), page_rows as (
    select record, started_at
    from filtered
    order by started_at desc
    offset v_from limit v_limit
  )
  select jsonb_build_object(
    'records', coalesce((select jsonb_agg(record order by started_at desc) from page_rows), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result;

  return v_result;
end;
$$;


ALTER FUNCTION "app_private"."search_workflow_instances_for_monitor"("p_keyword" "text", "p_business_type" "text", "p_status" "text", "p_sla_status" "text", "p_from" integer, "p_to" integer) OWNER TO "postgres";

