--

--
-- Name: set_hr_employee_creator_identity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."set_hr_employee_creator_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
  v_current_tenant_id uuid := app_private.auth_user_tenant_id();
begin
  if tg_op = 'INSERT' then
    if v_current_user_id is not null and v_current_tenant_id = new.tenant_id then
      if new.created_by_user_id is null then
        new.created_by_user_id := v_current_user_id;
      elsif new.created_by_user_id <> v_current_user_id then
        raise exception 'Employee creator must be the current tenant user'
          using errcode = '42501';
      end if;
    elsif v_current_user_id is not null and not app_private.is_platform_super() then
      raise exception 'Employee tenant must match the current user tenant'
        using errcode = '42501';
    elsif new.created_by_user_id is null
      and nullif(btrim(coalesce(new.create_by, '')), '') is not null then
      select user_row.id into new.created_by_user_id
      from public.sys_user user_row
      where user_row.tenant_id = new.tenant_id
        and (
          user_row.auth_user_id::text = new.create_by
          or lower(user_row.user_email) = lower(new.create_by)
        )
      order by
        case when user_row.auth_user_id::text = new.create_by then 0 else 1 end,
        user_row.create_time,
        user_row.id
      limit 1;
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Employee creator cannot be changed' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."set_hr_employee_creator_identity"() OWNER TO "postgres";

--

--
-- Name: set_tms_customer_creator_identity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."set_tms_customer_creator_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin
  if tg_op = 'INSERT' then
    if (select auth.uid()) is not null then
      if v_current_user_id is null then
        raise exception 'Authenticated application user not found' using errcode = '42501';
      end if;
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null then
      raise exception 'Creator identity is required';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Creator identity is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."set_tms_customer_creator_identity"() OWNER TO "postgres";

--

--
-- Name: set_tms_financial_document_creator_identity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."set_tms_financial_document_creator_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
begin
  if tg_op = 'INSERT' then
    if v_current_user_id is not null then
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null then
      select user_row.id
      into new.created_by_user_id
      from public.sys_user user_row
      where user_row.tenant_id = new.tenant_id
        and user_row.deleted_at is null
        and (
          lower(user_row.user_email) = lower(new.create_by)
          or lower(user_row.user_name) = lower(new.create_by)
          or lower(user_row.nick_name) = lower(new.create_by)
        )
      order by
        case
          when lower(user_row.user_email) = lower(new.create_by) then 0
          when lower(user_row.user_name) = lower(new.create_by) then 1
          else 2
        end,
        user_row.create_time,
        user_row.id
      limit 1;
    end if;

    if new.created_by_user_id is null then
      raise exception 'Authenticated financial document creator identity is required'
        using errcode = '42501';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Financial document creator identity is immutable' using errcode = '42501';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "app_private"."set_tms_financial_document_creator_identity"() OWNER TO "postgres";

--

--
-- Name: set_vehicle_supplier_creator_identity(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."set_vehicle_supplier_creator_identity"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_user_id uuid := app_private.current_app_user_id();
  v_current_user_tenant_id uuid;
begin
  if tg_op = 'INSERT' then
    if v_current_user_id is not null then
      select user_row.tenant_id into v_current_user_tenant_id
      from public.sys_user user_row where user_row.id = v_current_user_id;
    end if;
    if v_current_user_id is not null and (v_current_user_tenant_id = new.tenant_id or app_private.is_platform_super()) then
      new.created_by_user_id := v_current_user_id;
    elsif new.created_by_user_id is null and nullif(btrim(new.create_by), '') is not null then
      select user_row.id into new.created_by_user_id
      from public.sys_user user_row
      where user_row.tenant_id = new.tenant_id
        and lower(user_row.user_email) = lower(new.create_by)
        and user_row.deleted_at is null
      order by user_row.create_time, user_row.id limit 1;
    end if;
    if new.created_by_user_id is null or not exists (
      select 1 from public.sys_user user_row
      where user_row.id = new.created_by_user_id and (user_row.tenant_id = new.tenant_id or (app_private.is_platform_super() and user_row.id = v_current_user_id))
    ) then
      raise exception 'Vehicle supplier creator is missing or outside the record tenant'
        using errcode = '42501';
    end if;
  elsif new.created_by_user_id is distinct from old.created_by_user_id then
    raise exception 'Vehicle supplier creator identity is immutable' using errcode = '42501';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."set_vehicle_supplier_creator_identity"() OWNER TO "postgres";

--

--
-- Name: set_workflow_definition_enabled("uuid", boolean); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."set_workflow_definition_enabled"("p_definition_id" "uuid", "p_enabled" boolean) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_current_tenant_id uuid := (select app_private.current_user_tenant_id());
  v_target_tenant_id uuid;
  v_is_platform_super boolean := (select app_private.is_platform_super());
  v_definition public.wf_definition;
begin
  if (select auth.uid()) is null or not v_is_platform_super then
    raise exception '当前账号没有流程启停权限' using errcode = '42501';
  end if;

  select *
  into v_definition
  from public.wf_definition d
  where d.id = p_definition_id
    and (v_is_platform_super or d.tenant_id = v_current_tenant_id)
  for update;

  if not found then
    raise exception '流程不存在或无权操作';
  end if;

  v_target_tenant_id := v_definition.tenant_id;

  if p_enabled and v_definition.current_version_id is null then
    raise exception '流程尚未发布，不能启用';
  end if;

  if p_enabled and exists (
    select 1
    from public.wf_definition d
    where d.tenant_id = v_target_tenant_id
      and d.business_type = v_definition.business_type
      and d.status = 'published'
      and d.id <> v_definition.id
  ) then
    raise exception '该业务类型已有启用流程';
  end if;

  update public.wf_definition
  set status = case when p_enabled then 'published' else 'disabled' end
  where id = p_definition_id;
end;
$$;


ALTER FUNCTION "app_private"."set_workflow_definition_enabled"("p_definition_id" "uuid", "p_enabled" boolean) OWNER TO "postgres";

--

--
-- Name: start_workflow("text", "uuid", "text", "jsonb", "text"); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb", "p_idempotency_key" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_user_id uuid := app_private.current_app_user_id();
  v_actor text := coalesce(nullif(auth.jwt() ->> 'email', ''), auth.uid()::text);
  v_actor_name text;
  v_definition public.wf_definition;
  v_instance_id uuid;
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_business record;
begin
  if auth.uid() is null or v_user_id is null then raise exception '当前登录用户未绑定业务账号'; end if;
  if jsonb_typeof(v_context) <> 'object' then raise exception '流程上下文必须是对象'; end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_tenant_id::text || ':' || p_business_type || ':' || p_business_id::text, 91311
  ));
  select id into v_instance_id from public.wf_instance
  where tenant_id = v_tenant_id and business_type = p_business_type
    and business_id = p_business_id and status = 'running';
  if found then return v_instance_id; end if;

  select coalesce(nullif(nick_name, ''), nullif(user_name, ''), user_email, id::text)
  into v_actor_name from public.sys_user
  where id = v_user_id and tenant_id = v_tenant_id and status = '1';
  select * into v_definition from public.wf_definition
  where tenant_id = v_tenant_id and business_type = p_business_type and status = 'published';
  if not found then raise exception '当前业务类型没有已启用的审批流程'; end if;

  if p_business_type = 'tms_waybill_cost' then
    select c.id, c.audit_status business_status, c.amount, c.cost_type, c.waybill_id
    into v_business from public.tms_waybill_cost c
    where c.id = p_business_id and c.tenant_id = v_tenant_id for update;
    if not found then raise exception '运单费用不存在或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前费用状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.amount, 'costType', v_business.cost_type, 'waybillId', v_business.waybill_id
    );
  elsif p_business_type = 'tms_in_transit_expense' then
    raise exception '在途费用申报功能已停用，请使用运单费用流程';
  elsif p_business_type = 'tms_expense_reimbursement' then
    select r.id, r.status business_status, r.total_amount, r.reimbursement_no,
           r.payment_method, r.planned_payment_date,
           (select count(*)::integer from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) item_count,
           (select count(distinct i.waybill_id)::integer
            from public.tms_expense_reimbursement_item i
            where i.reimbursement_id = r.id) waybill_count
    into v_business from public.tms_expense_reimbursement r
    where r.id = p_business_id and r.tenant_id = v_tenant_id
    for update;
    if not found then raise exception '费用报销单不存在、无明细或无权提交'; end if;
    if v_business.business_status not in ('draft', 'rejected') then raise exception '当前报销单状态不允许提交审批'; end if;
    v_context := v_context || jsonb_build_object(
      'amount', v_business.total_amount, 'reimbursementNo', v_business.reimbursement_no,
      'paymentMethod', v_business.payment_method, 'plannedPaymentDate', v_business.planned_payment_date,
      'itemCount', v_business.item_count, 'waybillCount', v_business.waybill_count
    );
  end if;

  insert into public.wf_instance(
    definition_id, version_id, business_type, business_id, business_title,
    initiator_user_id, initiator_name_snapshot, context_snapshot, tenant_id, create_by, update_by
  ) values (
    v_definition.id, v_definition.current_version_id, p_business_type, p_business_id,
    btrim(p_business_title), v_user_id, v_actor_name, v_context, v_tenant_id, v_actor, v_actor
  ) returning id into v_instance_id;
  insert into public.wf_action(
    instance_id, action, actor_user_id, actor_name_snapshot, comment,
    idempotency_key, tenant_id, create_by
  ) values (
    v_instance_id, 'submit', v_user_id, v_actor_name, '提交审批',
    nullif(p_idempotency_key, ''), v_tenant_id, v_actor
  );
  perform app_private.apply_workflow_business_status(
    p_business_type, p_business_id, 'running', v_actor_name, null
  );
  perform app_private.activate_next_workflow_node(v_instance_id, 0);
  return v_instance_id;
end;
$$;


ALTER FUNCTION "app_private"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";

--

--
-- Name: sync_delete_auth_user_on_app_delete(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."sync_delete_auth_user_on_app_delete"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if old.auth_user_id is not null
     and exists (
       select 1
       from auth.users
       where id = old.auth_user_id
     )
  then
    delete from auth.users
    where id = old.auth_user_id;
  end if;

  return old;
end;
$$;


ALTER FUNCTION "app_private"."sync_delete_auth_user_on_app_delete"() OWNER TO "postgres";

--

--
-- Name: sync_notification_subject_from_source(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."sync_notification_subject_from_source"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_status text := case when tg_op = 'DELETE' then 'cancelled' else 'active' end;
  v_tenant_id uuid := (v_row ->> 'tenant_id')::uuid;
  v_business_id uuid := (v_row ->> 'id')::uuid;
begin
  if tg_table_name = 'sys_tenant' then
    v_tenant_id := v_business_id;
    if coalesce(v_row ->> 'status', '0') <> '1' then v_status := 'cancelled'; end if;
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'tenant_expiry', 'sys_tenant', v_business_id, 'service_end',
      coalesce(v_row ->> 'tenant_name', '租户') || ' 服务到期',
      case when v_row ->> 'service_end_date' is null then null
        else ((v_row ->> 'service_end_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/system/tenant', jsonb_build_object('tenantId', v_business_id), '{}'::jsonb, v_status
    );
  elsif tg_table_name = 'tms_contract' then
    if coalesce((v_row ->> 'is_completed')::boolean, false) then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'tms_contract_expiry', 'tms_contract', v_business_id, 'expiry_date',
      '运输合同「' || coalesce(v_row ->> 'contract_name', v_row ->> 'contract_no', '未命名') || '」到期',
      case when v_row ->> 'expiry_date' is null then null
        else ((v_row ->> 'expiry_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      nullif(v_row ->> 'created_by_user_id', '')::uuid,
      '/tms/basic-data/contract', jsonb_build_object('contractId', v_business_id),
      jsonb_build_object('businessNo', v_row ->> 'contract_no'), v_status
    );
  elsif tg_table_name = 'fms_commercial_bill' then
    if coalesce(v_row ->> 'status', '') in ('settled', 'cancelled', 'voided') then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'fms_commercial_bill_due', 'fms_commercial_bill', v_business_id, 'due_date',
      '商业票据「' || coalesce(v_row ->> 'bill_no', '未编号') || '」到期',
      case when v_row ->> 'due_date' is null then null
        else ((v_row ->> 'due_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/fms/commercial-bill', jsonb_build_object('billId', v_business_id),
      jsonb_build_object('businessNo', v_row ->> 'bill_no'), v_status
    );
  elsif tg_table_name = 'vehicle_insurance' then
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'vms_commercial_insurance_expiry', 'vehicle_insurance', v_business_id, 'commercial',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 商业险到期',
      case when v_row ->> 'commercial_expire_date' is null then null
        else ((v_row ->> 'commercial_expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/insurance-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'vms_compulsory_insurance_expiry', 'vehicle_insurance', v_business_id, 'compulsory',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 交强险到期',
      case when v_row ->> 'compulsory_expire_date' is null then null
        else ((v_row ->> 'compulsory_expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/insurance-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  elsif tg_table_name = 'vehicle_inspection' then
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'vms_vehicle_inspection_expiry', 'vehicle_inspection', v_business_id, 'expire_date',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 年检到期',
      case when v_row ->> 'expire_date' is null then null
        else ((v_row ->> 'expire_date')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/inspection-expiry', jsonb_build_object('vehicleId', v_row ->> 'vehicle_id'),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  elsif tg_table_name = 'vehicle_archive' then
    if coalesce(v_row ->> 'operation_status', '') in ('scrapped', 'retired', 'inactive') then v_status := 'resolved'; end if;
    perform app_private.upsert_notification_subject(
      v_tenant_id, 'vms_vehicle_service_expiry', 'vehicle_archive', v_business_id, 'service_end',
      coalesce(v_row ->> 'plate_no', '车辆') || ' 服务期到期',
      case when v_row ->> 'service_end_time' is null then null
        else ((v_row ->> 'service_end_time')::date + time '09:00') at time zone 'Asia/Shanghai' end,
      null, '/vms/reminder-manage/vehicle-service-life', jsonb_build_object('vehicleId', v_business_id),
      jsonb_build_object('plateNo', v_row ->> 'plate_no'), v_status
    );
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "app_private"."sync_notification_subject_from_source"() OWNER TO "postgres";

--

--
-- Name: sync_scm_purchase_request(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."sync_scm_purchase_request"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_source_id uuid;
  v_request public.scm_purchase_document%rowtype;
  v_total numeric;
  v_used numeric;
begin
  v_source_id:=case when tg_op='DELETE' then old.source_id else new.source_id end;
  if v_source_id is null or (case when tg_op='DELETE' then old.kind else new.kind end)<>'purchase_order' then
    return null;
  end if;
  select * into v_request from public.scm_purchase_document where id=v_source_id for update;
  if v_request.id is null then return null; end if;
  select coalesce(sum((l.value->>'quantity')::numeric),0) into v_total
    from jsonb_array_elements(v_request.lines) l;
  select coalesce(sum((l.value->>'quantity')::numeric),0) into v_used
    from public.scm_purchase_document d cross join lateral jsonb_array_elements(d.lines) l
    where d.source_id=v_source_id and d.kind='purchase_order' and d.status<>'cancelled'
      and l.value->>'source_line_id' is not null;
  update public.scm_purchase_document set status=case
    when v_used=0 then 'draft' when v_used>=v_total then 'completed' else 'purchasing' end
    where id=v_source_id and status is distinct from case
      when v_used=0 then 'draft' when v_used>=v_total then 'completed' else 'purchasing' end;
  return null;
end
$$;


ALTER FUNCTION "app_private"."sync_scm_purchase_request"() OWNER TO "postgres";

