CREATE TABLE IF NOT EXISTS "public"."mdm_customer_address" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "customer_id" "uuid",
    "address_type" "text" NOT NULL,
    "contact_name" "text" NOT NULL,
    "contact_phone" "text" NOT NULL,
    "region" "text" NOT NULL,
    "address_detail" "text" NOT NULL,
    "postal_code" "text",
    "is_default" boolean DEFAULT false NOT NULL,
    "remark" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "region_adcode" "text",
    "longitude" numeric(11,7),
    "latitude" numeric(10,7),
    "coordinate_system" "text" DEFAULT 'gcj02'::"text" NOT NULL,
    "coordinate_source" "text",
    "coordinate_status" "text" DEFAULT 'pending'::"text" NOT NULL,
    "geocode_provider" "text",
    "geocoded_at" timestamp with time zone,
    "geofence_enabled" boolean DEFAULT false NOT NULL,
    "geofence_radius_m" integer,
    "geofence_updated_at" timestamp with time zone,
    "created_by_user_id" "uuid" NOT NULL,
    "party_name" "text",
    "address_short_name" "text",
    "business_hours_start" time without time zone,
    "business_hours_end" time without time zone,
    CONSTRAINT "mdm_customer_address_business_hours_pair" CHECK (((("business_hours_start" IS NULL) AND ("business_hours_end" IS NULL)) OR (("business_hours_start" IS NOT NULL) AND ("business_hours_end" IS NOT NULL) AND ("business_hours_start" < "business_hours_end")))),
    CONSTRAINT "mdm_customer_address_party_name_length" CHECK ((("party_name" IS NULL) OR ("char_length"("btrim"("party_name")) <= 100))),
    CONSTRAINT "mdm_customer_address_short_name_length" CHECK ((("address_short_name" IS NULL) OR (("char_length"("btrim"("address_short_name")) >= 1) AND ("char_length"("btrim"("address_short_name")) <= 20)))),
    CONSTRAINT "tms_customer_address_contact_not_blank" CHECK (("btrim"("contact_name") <> ''::"text")),
    CONSTRAINT "tms_customer_address_detail_not_blank" CHECK (("btrim"("address_detail") <> ''::"text")),
    CONSTRAINT "tms_customer_address_geofence_radius_check" CHECK ((("geofence_radius_m" IS NULL) OR (("geofence_radius_m" >= 50) AND ("geofence_radius_m" <= 50000)))),
    CONSTRAINT "tms_customer_address_geofence_ready_check" CHECK (((NOT "geofence_enabled") OR (("longitude" IS NOT NULL) AND ("latitude" IS NOT NULL) AND ("geofence_radius_m" IS NOT NULL)))),
    CONSTRAINT "tms_customer_address_latitude_check" CHECK ((("latitude" IS NULL) OR (("latitude" >= ('-90'::integer)::numeric) AND ("latitude" <= (90)::numeric)))),
    CONSTRAINT "tms_customer_address_longitude_check" CHECK ((("longitude" IS NULL) OR (("longitude" >= ('-180'::integer)::numeric) AND ("longitude" <= (180)::numeric)))),
    CONSTRAINT "tms_customer_address_type_check" CHECK (("address_type" = ANY (ARRAY['shipping'::"text", 'receiving'::"text"])))
);


