--
-- Name: trg_number_scm_purchase_contract(); Type: FUNCTION; Schema: app_private
--

--

CREATE OR REPLACE FUNCTION "app_private"."trg_number_scm_purchase_contract"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
 if new.kind='purchase_contract' then
   new.document_no:=app_private.next_document_number('scm.purchase_contract',new.tenant_id);
 elsif new.kind='purchase_request' then
   new.document_no:=app_private.next_document_number('scm.purchase_request',new.tenant_id);
 elsif new.kind='purchase_order' then
   new.document_no:=app_private.next_document_number('scm.purchase_order',new.tenant_id);
 elsif new.kind='receipt_notice' then
   new.document_no:=app_private.next_document_number('scm.receipt_notice',new.tenant_id);
 end if;
 return new;
end
$$;


