--

--
-- Name: ai_ocr_quality_overview(integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."ai_ocr_quality_overview"("p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
with features(feature, label) as (values
  ('invoice_ocr','发票 OCR'), ('waybill_receipt_ocr','签收回单 OCR'),
  ('cash_voucher_ocr','收付款凭证 OCR'), ('bank_statement_batch_match','银行流水批量匹配')
), scoped as (
  select a.* from public.ai_artifact_review a
  where a.feature in (select feature from features)
    and a.create_time >= now() - make_interval(days => least(greatest(coalesce(p_days,30),1),90))
), stats as (
  select f.feature, f.label,
    count(s.id)::int artifacts,
    count(s.id) filter (where s.status <> 'pending')::int reviewed,
    count(s.id) filter (where s.status = 'applied')::int applied,
    coalesce(round(avg(s.confidence) * 100,1),0) average_confidence,
    coalesce(sum(cardinality(s.accepted_fields)),0)::int accepted_fields,
    coalesce(sum(cardinality(s.corrected_fields)),0)::int corrected_fields
  from features f left join scoped s on s.feature=f.feature group by f.feature,f.label
), enriched as (
  select stats.*, coalesce(t.review_confidence_threshold,0.820) threshold,
    count(s.id) filter (where s.confidence < coalesce(t.review_confidence_threshold,0.820))::int low_confidence
  from stats left join public.ai_ocr_quality_threshold t on t.feature=stats.feature
    and (t.tenant_id=app_private.current_user_tenant_id() or app_private.is_platform_super())
  left join scoped s on s.feature=stats.feature
  group by stats.feature,stats.label,stats.artifacts,stats.reviewed,stats.applied,stats.average_confidence,
    stats.accepted_fields,stats.corrected_fields,t.review_confidence_threshold
)
select jsonb_build_object(
  'days', least(greatest(coalesce(p_days,30),1),90),
  'canManage', app_private.is_platform_super(),
  'totalArtifacts', sum(artifacts),
  'reviewedArtifacts', sum(reviewed),
  'lowConfidenceArtifacts', sum(low_confidence),
  'acceptedFields', sum(accepted_fields),
  'correctedFields', sum(corrected_fields),
  'features', coalesce(jsonb_agg(jsonb_build_object(
    'feature',feature,'label',label,'artifacts',artifacts,'reviewed',reviewed,'applied',applied,
    'averageConfidence',average_confidence,'acceptedFields',accepted_fields,'correctedFields',corrected_fields,
    'acceptanceRate',case when accepted_fields+corrected_fields=0 then 0 else round(accepted_fields*100.0/(accepted_fields+corrected_fields),1) end,
    'threshold',round(threshold*100,1),'lowConfidence',low_confidence,
    'recommendedThreshold',round((case
      when reviewed < 5 then threshold
      when accepted_fields+corrected_fields > 0 and accepted_fields*1.0/(accepted_fields+corrected_fields) < .80 then least(.95,threshold+.05)
      when accepted_fields+corrected_fields > 0 and accepted_fields*1.0/(accepted_fields+corrected_fields) > .95 then greatest(.65,threshold-.03)
      else threshold end)*100,1)
  ) order by feature), '[]'::jsonb)
) from enriched;
$$;


ALTER FUNCTION "public"."ai_ocr_quality_overview"("p_days" integer) OWNER TO "postgres";

--

--
-- Name: ai_ocr_recognition_overview(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."ai_ocr_recognition_overview"() RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with visible_reviews as materialized (
    select
      review.feature,
      review.status,
      review.confidence,
      review.create_time
    from public.ai_artifact_review review
    where review.feature in (
      'invoice_ocr',
      'waybill_receipt_ocr',
      'cash_voucher_ocr',
      'waybill_expense_ocr'
    )
  ),
  summary as (
    select
      count(*) as total,
      count(*) filter (where status = 'pending') as pending,
      count(*) filter (where status = 'applied') as applied,
      count(*) filter (where status = 'rejected') as rejected,
      count(*) filter (where coalesce(confidence, 0) < 0.65) as low_confidence,
      count(*) filter (
        where status = 'pending' and coalesce(confidence, 0) < 0.65
      ) as pending_low_confidence,
      count(*) filter (where create_time >= date_trunc('day', now())) as today,
      coalesce(round(avg(confidence), 4), 0) as avg_confidence
    from visible_reviews
  ),
  feature_stats as (
    select feature, count(*) as feature_count
    from visible_reviews
    group by feature
  )
  select jsonb_build_object(
    'total', summary.total,
    'pending', summary.pending,
    'applied', summary.applied,
    'rejected', summary.rejected,
    'low_confidence', summary.low_confidence,
    'pending_low_confidence', summary.pending_low_confidence,
    'today', summary.today,
    'avg_confidence', summary.avg_confidence,
    'by_feature', coalesce(
      (select jsonb_object_agg(feature, feature_count) from feature_stats),
      '{}'::jsonb
    )
  )
  from summary;
$$;


ALTER FUNCTION "public"."ai_ocr_recognition_overview"() OWNER TO "postgres";

--

--
-- Name: ai_operations_overview(integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."ai_operations_overview"("p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with params as (
    select least(greatest(coalesce(p_days, 30), 1), 90) as days
  ),
  scoped_runs as (
    select run.*
    from public.ai_run run
    cross join params
    where run.started_at >= current_timestamp - make_interval(days => params.days)
  ),
  totals as (
    select
      count(*)::bigint as total_runs,
      count(*) filter (where status = 'succeeded')::bigint as succeeded_runs,
      count(*) filter (where status = 'failed')::bigint as failed_runs,
      count(*) filter (where status = 'running')::bigint as running_runs,
      coalesce(round(avg(latency_ms) filter (where latency_ms is not null)), 0)::bigint
        as average_latency_ms,
      coalesce(
        round(percentile_cont(0.95) within group (order by latency_ms)
          filter (where latency_ms is not null)),
        0
      )::bigint as p95_latency_ms,
      coalesce(sum(input_tokens), 0)::bigint as input_tokens,
      coalesce(sum(output_tokens), 0)::bigint as output_tokens
    from scoped_runs
  ),
  feedback_totals as (
    select
      count(*) filter (where feedback.rating = 1)::bigint as positive_feedback,
      count(*) filter (where feedback.rating = -1)::bigint as negative_feedback
    from public.ai_feedback feedback
    join scoped_runs run on run.id = feedback.run_id
  ),
  scoped_artifacts as (
    select artifact.*
    from public.ai_artifact_review artifact
    cross join params
    where artifact.create_time >= current_timestamp - make_interval(days => params.days)
  ),
  quality_totals as (
    select
      count(*)::bigint as total_artifacts,
      count(*) filter (where status = 'pending')::bigint as pending_artifacts,
      count(*) filter (where status <> 'pending')::bigint as reviewed_artifacts,
      count(*) filter (where status = 'applied')::bigint as applied_artifacts,
      count(*) filter (where status = 'rejected')::bigint as rejected_artifacts,
      count(*) filter (where status = 'superseded')::bigint as superseded_artifacts,
      coalesce(sum(cardinality(accepted_fields)), 0)::bigint as accepted_fields,
      coalesce(sum(cardinality(corrected_fields)), 0)::bigint as corrected_fields,
      coalesce(round(avg(confidence) filter (where confidence is not null) * 100, 1), 0)
        as average_confidence
    from scoped_artifacts
  ),
  field_events as (
    select field, true as accepted
    from scoped_artifacts artifact
    cross join lateral unnest(artifact.accepted_fields) as field
    where artifact.status = 'applied'
    union all
    select field, false as accepted
    from scoped_artifacts artifact
    cross join lateral unnest(artifact.corrected_fields) as field
    where artifact.status = 'applied'
  ),
  day_series as (
    select generate_series(
      current_date - ((select days from params) - 1),
      current_date,
      interval '1 day'
    )::date as day
  ),
  daily_counts as (
    select
      started_at::date as day,
      count(*)::bigint as total,
      count(*) filter (where status = 'succeeded')::bigint as succeeded,
      count(*) filter (where status = 'failed')::bigint as failed
    from scoped_runs
    group by started_at::date
  ),
  daily_quality as (
    select
      artifact.create_time::date as day,
      count(*)::bigint as total,
      count(*) filter (where artifact.status = 'applied')::bigint as applied,
      count(*) filter (where artifact.status = 'rejected')::bigint as rejected,
      coalesce(sum(cardinality(artifact.accepted_fields)), 0)::bigint as accepted_fields,
      coalesce(sum(cardinality(artifact.corrected_fields)), 0)::bigint as corrected_fields
    from scoped_artifacts artifact
    group by artifact.create_time::date
  )
  select jsonb_build_object(
    'days', params.days,
    'totalRuns', totals.total_runs,
    'succeededRuns', totals.succeeded_runs,
    'failedRuns', totals.failed_runs,
    'runningRuns', totals.running_runs,
    'successRate', case
      when totals.total_runs = 0 then 0
      else round(totals.succeeded_runs::numeric * 100 / totals.total_runs, 1)
    end,
    'averageLatencyMs', totals.average_latency_ms,
    'p95LatencyMs', totals.p95_latency_ms,
    'inputTokens', totals.input_tokens,
    'outputTokens', totals.output_tokens,
    'positiveFeedback', feedback_totals.positive_feedback,
    'negativeFeedback', feedback_totals.negative_feedback,
    'dailyTrend', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'date', day_series.day,
          'total', coalesce(daily_counts.total, 0),
          'succeeded', coalesce(daily_counts.succeeded, 0),
          'failed', coalesce(daily_counts.failed, 0)
        )
        order by day_series.day
      )
      from day_series
      left join daily_counts on daily_counts.day = day_series.day
    ), '[]'::jsonb),
    'featureBreakdown', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'feature', feature_stats.feature,
          'total', feature_stats.total,
          'succeeded', feature_stats.succeeded,
          'failed', feature_stats.failed,
          'averageLatencyMs', feature_stats.average_latency_ms
        )
        order by feature_stats.total desc, feature_stats.feature
      )
      from (
        select
          feature,
          count(*)::bigint as total,
          count(*) filter (where status = 'succeeded')::bigint as succeeded,
          count(*) filter (where status = 'failed')::bigint as failed,
          coalesce(round(avg(latency_ms) filter (where latency_ms is not null)), 0)::bigint
            as average_latency_ms
        from scoped_runs
        group by feature
      ) feature_stats
    ), '[]'::jsonb),
    'topErrors', coalesce((
      select jsonb_agg(
        jsonb_build_object('code', error_stats.error_code, 'count', error_stats.total)
        order by error_stats.total desc, error_stats.error_code
      )
      from (
        select coalesce(error_code, 'unknown_error') as error_code, count(*)::bigint as total
        from scoped_runs
        where status = 'failed'
        group by coalesce(error_code, 'unknown_error')
        order by total desc
        limit 5
      ) error_stats
    ), '[]'::jsonb),
    'quality', jsonb_build_object(
      'totalArtifacts', quality_totals.total_artifacts,
      'pendingArtifacts', quality_totals.pending_artifacts,
      'reviewedArtifacts', quality_totals.reviewed_artifacts,
      'appliedArtifacts', quality_totals.applied_artifacts,
      'rejectedArtifacts', quality_totals.rejected_artifacts,
      'supersededArtifacts', quality_totals.superseded_artifacts,
      'reviewCompletionRate', case
        when quality_totals.total_artifacts = 0 then 0
        else round(
          quality_totals.reviewed_artifacts::numeric * 100 / quality_totals.total_artifacts,
          1
        )
      end,
      'applicationRate', case
        when quality_totals.total_artifacts = 0 then 0
        else round(
          quality_totals.applied_artifacts::numeric * 100 / quality_totals.total_artifacts,
          1
        )
      end,
      'acceptedFields', quality_totals.accepted_fields,
      'correctedFields', quality_totals.corrected_fields,
      'fieldAcceptanceRate', case
        when quality_totals.accepted_fields + quality_totals.corrected_fields = 0 then 0
        else round(
          quality_totals.accepted_fields::numeric * 100
            / (quality_totals.accepted_fields + quality_totals.corrected_fields),
          1
        )
      end,
      'averageConfidence', quality_totals.average_confidence,
      'dailyTrend', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'date', day_series.day,
            'total', coalesce(daily_quality.total, 0),
            'applied', coalesce(daily_quality.applied, 0),
            'rejected', coalesce(daily_quality.rejected, 0),
            'acceptedFields', coalesce(daily_quality.accepted_fields, 0),
            'correctedFields', coalesce(daily_quality.corrected_fields, 0)
          )
          order by day_series.day
        )
        from day_series
        left join daily_quality on daily_quality.day = day_series.day
      ), '[]'::jsonb),
      'fieldQuality', coalesce((
        select jsonb_agg(
          jsonb_build_object(
            'field', field_stats.field,
            'total', field_stats.total,
            'accepted', field_stats.accepted,
            'corrected', field_stats.corrected,
            'acceptanceRate', case
              when field_stats.total = 0 then 0
              else round(field_stats.accepted::numeric * 100 / field_stats.total, 1)
            end
          )
          order by field_stats.corrected desc, field_stats.total desc, field_stats.field
        )
        from (
          select
            field,
            count(*)::bigint as total,
            count(*) filter (where accepted)::bigint as accepted,
            count(*) filter (where not accepted)::bigint as corrected
          from field_events
          group by field
          order by corrected desc, total desc, field
          limit 12
        ) field_stats
      ), '[]'::jsonb)
    )
  )
  from params
  cross join totals
  cross join feedback_totals
  cross join quality_totals;
$$;


ALTER FUNCTION "public"."ai_operations_overview"("p_days" integer) OWNER TO "postgres";

--

--
-- Name: ai_quality_feedback_overview(integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."ai_quality_feedback_overview"("p_days" integer DEFAULT 30) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  with params as (
    select least(greatest(coalesce(p_days, 30), 1), 90) as days
  ),
  scoped_runs as (
    select run.*
    from public.ai_run run
    cross join params
    where run.started_at >= current_timestamp - make_interval(days => params.days)
  ),
  scoped_feedback as (
    select feedback.*, resolution.status as resolution_status,
      resolution.issue_type, resolution.resolution_note,
      resolution.handled_by, resolution.resolved_by,
      resolution.resolved_at, resolution.update_time as resolution_update_time
    from public.ai_feedback feedback
    join scoped_runs run on run.id = feedback.run_id
    left join public.ai_feedback_resolution resolution on resolution.feedback_id = feedback.id
  ),
  totals as (
    select
      (select count(*) from scoped_runs)::bigint as total_runs,
      count(*)::bigint as total_feedback,
      count(*) filter (where rating = 1)::bigint as positive_feedback,
      count(*) filter (where rating = -1)::bigint as negative_feedback,
      count(*) filter (
        where rating = -1 and coalesce(resolution_status, 'open') in ('open', 'in_progress')
      )::bigint as open_feedback_issues,
      count(*) filter (
        where rating = -1 and resolution_status in ('resolved', 'dismissed')
      )::bigint as closed_feedback_issues
    from scoped_feedback
  )
  select jsonb_build_object(
    'days', params.days,
    'canManageFeedback',
      (select app_private.is_platform_super()) or (select app_private.is_tenant_admin()),
    'totalRuns', totals.total_runs,
    'totalFeedback', totals.total_feedback,
    'unratedRuns', greatest(totals.total_runs - totals.total_feedback, 0),
    'feedbackCoverageRate', case
      when totals.total_runs = 0 then 0
      else round(totals.total_feedback::numeric * 100 / totals.total_runs, 1)
    end,
    'positiveFeedback', totals.positive_feedback,
    'negativeFeedback', totals.negative_feedback,
    'positiveRate', case
      when totals.total_feedback = 0 then 0
      else round(totals.positive_feedback::numeric * 100 / totals.total_feedback, 1)
    end,
    'openFeedbackIssues', totals.open_feedback_issues,
    'closedFeedbackIssues', totals.closed_feedback_issues,
    'resolutionRate', case
      when totals.negative_feedback = 0 then 100
      else round(totals.closed_feedback_issues::numeric * 100 / totals.negative_feedback, 1)
    end,
    'featureQuality', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'feature', stats.feature,
          'totalRuns', stats.total_runs,
          'successRate', stats.success_rate,
          'feedbackCount', stats.feedback_count,
          'feedbackCoverageRate', stats.feedback_coverage_rate,
          'positiveFeedback', stats.positive_feedback,
          'negativeFeedback', stats.negative_feedback,
          'openIssues', stats.open_issues
        )
        order by stats.open_issues desc, stats.feedback_coverage_rate asc, stats.total_runs desc
      )
      from (
        select
          run.feature,
          count(distinct run.id)::bigint as total_runs,
          round(
            count(distinct run.id) filter (where run.status = 'succeeded')::numeric
              * 100 / nullif(count(distinct run.id), 0),
            1
          ) as success_rate,
          count(distinct feedback.id)::bigint as feedback_count,
          round(
            count(distinct feedback.id)::numeric * 100 / nullif(count(distinct run.id), 0),
            1
          ) as feedback_coverage_rate,
          count(distinct feedback.id) filter (where feedback.rating = 1)::bigint as positive_feedback,
          count(distinct feedback.id) filter (where feedback.rating = -1)::bigint as negative_feedback,
          count(distinct feedback.id) filter (
            where feedback.rating = -1
              and coalesce(resolution.status, 'open') in ('open', 'in_progress')
          )::bigint as open_issues
        from scoped_runs run
        left join public.ai_feedback feedback on feedback.run_id = run.id
        left join public.ai_feedback_resolution resolution on resolution.feedback_id = feedback.id
        group by run.feature
      ) stats
    ), '[]'::jsonb),
    'feedbackQueue', coalesce((
      select jsonb_agg(queue.item order by queue.is_closed, queue.feedback_time desc)
      from (
        select
          jsonb_build_object(
            'feedbackId', feedback.id,
            'runId', feedback.run_id,
            'feature', run.feature,
            'model', run.model,
            'comment', feedback.comment,
            'feedbackTime', feedback.create_time,
            'runStartedAt', run.started_at,
            'status', coalesce(resolution.status, 'open'),
            'issueType', coalesce(
              resolution.issue_type,
              nullif(feedback.correction ->> 'issueType', '')
            ),
            'resolutionNote', resolution.resolution_note,
            'resolvedAt', resolution.resolved_at,
            'handledBy', resolution.handled_by
          ) as item,
          (coalesce(resolution.status, 'open') in ('resolved', 'dismissed')) as is_closed,
          feedback.create_time as feedback_time
        from scoped_feedback feedback
        join scoped_runs run on run.id = feedback.run_id
        left join public.ai_feedback_resolution resolution on resolution.feedback_id = feedback.id
        where feedback.rating = -1
        order by is_closed, feedback.create_time desc
        limit 8
      ) queue
    ), '[]'::jsonb)
  )
  from params
  cross join totals;
$$;


ALTER FUNCTION "public"."ai_quality_feedback_overview"("p_days" integer) OWNER TO "postgres";

--

--
-- Name: apply_ai_ocr_quality_threshold("text", numeric, "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."apply_ai_ocr_quality_threshold"("p_feature" "text", "p_threshold" numeric, "p_reason" "text") RETURNS integer
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare v_count integer;
begin
  if not app_private.is_platform_super() then raise exception '仅平台超级管理员可调整 OCR 阈值'; end if;
  if p_feature not in ('invoice_ocr','waybill_receipt_ocr','cash_voucher_ocr','bank_statement_batch_match') then raise exception '不支持的 OCR 能力'; end if;
  if p_threshold < .5 or p_threshold > .99 then raise exception '阈值必须在 50%% 至 99%% 之间'; end if;
  if coalesce(length(trim(p_reason)),0) < 2 then raise exception '请填写阈值调整原因'; end if;
  insert into public.ai_ocr_quality_threshold(tenant_id,feature,review_confidence_threshold,change_reason)
  select id,p_feature,p_threshold,trim(p_reason) from public.sys_tenant where status='1'
  on conflict (tenant_id,feature) do update set review_confidence_threshold=excluded.review_confidence_threshold,
    change_reason=excluded.change_reason, update_time=now();
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;


ALTER FUNCTION "public"."apply_ai_ocr_quality_threshold"("p_feature" "text", "p_threshold" numeric, "p_reason" "text") OWNER TO "postgres";

