--
-- Name: create_tms_carrier_payment("uuid", "date", numeric, "text", "text", "jsonb", "text", "jsonb", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."create_tms_carrier_payment"("p_carrier_id" "uuid", "p_transaction_date" "date", "p_amount" numeric, "p_payment_method" "text", "p_bank_reference" "text", "p_voucher_urls" "jsonb", "p_remark" "text", "p_allocations" "jsonb", "p_transaction_no" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  perform set_config('app.document_number.tms_cash_transaction', coalesce(p_transaction_no, ''), true);
  return public.create_tms_carrier_payment(
    p_carrier_id, p_transaction_date, p_amount, p_payment_method,
    p_bank_reference, p_voucher_urls, p_remark, p_allocations
  );
end;
$$;


