--

--
-- Name: get_menus_for_current_applications("text"[]); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."get_menus_for_current_applications"("p_app_codes" "text"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb := '{}'::jsonb;
  v_app_code text;
begin
  if cardinality(p_app_codes) > 20 then
    raise exception '一次最多加载 20 个应用菜单' using errcode = '22023';
  end if;
  if (select auth.uid()) is null then
    return v_result;
  end if;
  for v_app_code in
    select distinct lower(nullif(btrim(code), ''))
    from unnest(p_app_codes) as requested(code)
    where nullif(btrim(code), '') is not null
  loop
    v_result := jsonb_set(
      v_result, array[v_app_code],
      app_private.get_authorized_application_menu_flat(v_app_code), true
    );
  end loop;
  return v_result;
end;
$$;


ALTER FUNCTION "public"."get_menus_for_current_applications"("p_app_codes" "text"[]) OWNER TO "postgres";

