--

--
-- Name: list_menu_management_nodes("uuid", "text", "text", "uuid", boolean, boolean); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."list_menu_management_nodes"("p_parent_id" "uuid" DEFAULT NULL::"uuid", "p_name" "text" DEFAULT NULL::"text", "p_path" "text" DEFAULT NULL::"text", "p_record_id" "uuid" DEFAULT NULL::"uuid", "p_root_only" boolean DEFAULT false, "p_include_child_state" boolean DEFAULT true) RETURNS "jsonb"
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select coalesce(
    jsonb_agg(
      to_jsonb(menu_row)
      || case
        when p_include_child_state then jsonb_build_object(
          'has_children',
          exists (
            select 1
            from public.sys_menu child_row
            where child_row.parent_id = menu_row.id
          )
        )
        else '{}'::jsonb
      end
      order by menu_row.sort nulls last, menu_row.id
    ),
    '[]'::jsonb
  )
  from public.sys_menu menu_row
  where case
      when p_parent_id is not null then menu_row.parent_id = p_parent_id
      when p_root_only then menu_row.parent_id is null
      else true
    end
    and (
      nullif(btrim(p_name), '') is null
      or coalesce(menu_row.meta ->> 'title', '') ilike '%' || btrim(p_name) || '%'
    )
    and (
      nullif(btrim(p_path), '') is null
      or menu_row.path = btrim(p_path)
    )
    and (p_record_id is null or menu_row.id = p_record_id);
$$;


ALTER FUNCTION "public"."list_menu_management_nodes"("p_parent_id" "uuid", "p_name" "text", "p_path" "text", "p_record_id" "uuid", "p_root_only" boolean, "p_include_child_state" boolean) OWNER TO "postgres";

