--

--
-- Name: normalize_login_phone("text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."normalize_login_phone"("p_phone" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE PARALLEL SAFE
    SET "search_path" TO ''
    AS $_$
  select case
    when normalized.digits = '' then null
    when normalized.digits ~ '^00861[3-9][0-9]{9}$' then '+' || substring(normalized.digits from 3)
    when normalized.digits ~ '^861[3-9][0-9]{9}$' then '+' || normalized.digits
    when normalized.digits ~ '^1[3-9][0-9]{9}$' then '+86' || normalized.digits
    when btrim(p_phone) like '+%' and normalized.digits ~ '^[0-9]{8,15}$' then '+' || normalized.digits
    else normalized.digits
  end
  from (select regexp_replace(coalesce(p_phone, ''), '[^0-9]', '', 'g') as digits) normalized;
$_$;


ALTER FUNCTION "public"."normalize_login_phone"("p_phone" "text") OWNER TO "postgres";

--

--
-- Name: prevent_platform_tenant_change(); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."prevent_platform_tenant_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    if old.builtin_type is not null then
      raise exception '系统预置租户“%”不可删除', old.tenant_name;
    end if;
    return old;
  end if;

  if old.builtin_type is not null then
    if new.builtin_type is distinct from old.builtin_type then
      raise exception '系统预置租户身份不可修改';
    end if;
    if new.tenant_code is distinct from old.tenant_code then
      raise exception '系统预置租户编码不可修改';
    end if;
    if new.status is distinct from '1' then
      raise exception '系统预置租户不可停用';
    end if;
  elsif new.builtin_type is not null then
    raise exception '不能将普通租户改为系统预置租户';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_platform_tenant_change"() OWNER TO "postgres";

