    CONSTRAINT "ai_prompt_template_feature_not_blank" CHECK (("btrim"("feature") <> ''::"text")),
    CONSTRAINT "ai_prompt_template_name_not_blank" CHECK (("btrim"("name") <> ''::"text")),
    CONSTRAINT "ai_prompt_template_prompt_length" CHECK ((("char_length"("btrim"("system_prompt")) >= 20) AND ("char_length"("btrim"("system_prompt")) <= 16000))),
    CONSTRAINT "ai_prompt_template_publish_fields_check" CHECK ((("status" <> 'published'::"text") OR (("published_at" IS NOT NULL) AND ("published_by" IS NOT NULL)))),
    CONSTRAINT "ai_prompt_template_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'archived'::"text"]))),
    CONSTRAINT "ai_prompt_template_version_format" CHECK (("version" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,31}$'::"text"))
);


