--

--
-- Name: scm_push_receipt_lines_secure("uuid", "uuid"[], "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."scm_push_receipt_lines_secure"("p_receipt_id" "uuid", "p_line_ids" "uuid"[], "p_target_kind" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_receipt public.scm_purchase_document%rowtype;
 v_doc_id uuid;
 v_line jsonb;
 v_line_id uuid;
 v_amount numeric;
 v_count integer := 0;
 v_total numeric := 0;
 v_permission text;
begin
 if p_target_kind not in ('inbound','asset_payable') or p_target_kind is null then
   raise exception '无效的下推目标' using errcode='22023';
 end if;
 v_permission := case p_target_kind when 'inbound' then 'WmsReceiptInbound:Add' else 'FinanceAssetPayable:Add' end;
 if not app_private.has_permission('ScmReceiptNotice:Push')
   or not app_private.has_permission(v_permission) then
   raise exception '没有下推或目标单据新增权限' using errcode='42501';
 end if;
 select * into v_receipt from public.scm_purchase_document
   where id=p_receipt_id and kind='receipt_notice' for update;
 if not found or v_receipt.status <> 'completed' then
   raise exception '只能下推已确认的收料通知单' using errcode='23514';
 end if;
 perform app_private.wms_resolve_write_tenant_id(v_receipt.tenant_id);
 if p_line_ids is null or cardinality(p_line_ids)=0
   or cardinality(p_line_ids) <> (select count(distinct x) from unnest(p_line_ids) x) then
   raise exception '请选择不重复的收料明细' using errcode='22023';
 end if;
 insert into public.scm_receipt_target_document
   (tenant_id,target_kind,document_no,source_receipt_id,project_id,construction_no,supplier_id,created_by_user_id)
 values (
   v_receipt.tenant_id,p_target_kind,
   (case p_target_kind when 'inbound' then 'SRK' else 'ZCYF' end)
     || to_char(now() at time zone 'Asia/Shanghai','YYYYMM')
     || '-' || lpad(nextval('public.scm_receipt_target_no_seq'::regclass)::text,7,'0'),
   v_receipt.id,v_receipt.project_id,
   case when p_target_kind='inbound' then nullif(btrim(coalesce(v_receipt.details->>'construction_no',v_receipt.details->>'constructionNo','')),'') else null end,
   v_receipt.supplier_id,auth.uid()
 ) returning id into v_doc_id;
 foreach v_line_id in array p_line_ids loop
   select item into v_line from jsonb_array_elements(v_receipt.lines) item
     where item->>'line_id'=v_line_id::text limit 1;
   if v_line is null then
     raise exception '所选明细不属于该收料通知单' using errcode='23514';
   end if;
   if coalesce((v_line->>'quantity')::numeric,0)<=0 then
     raise exception '收料明细数量必须大于零' using errcode='23514';
   end if;
   v_amount := case when coalesce((v_line->>'gift')::boolean,false) then 0 else
     round((v_line->>'quantity')::numeric * coalesce((v_line->>'unit_price')::numeric,0)
       * (1-coalesce((v_line->>'discount_rate')::numeric,0)/100),2)
     + round((v_line->>'quantity')::numeric * coalesce((v_line->>'unit_price')::numeric,0)
       * (1-coalesce((v_line->>'discount_rate')::numeric,0)/100)
       * coalesce((v_line->>'tax_rate')::numeric,0)/100,2)
     end;
   insert into public.scm_receipt_target_line
     (tenant_id,target_kind,target_document_id,source_receipt_id,source_line_id,line_snapshot,amount)
   values (v_receipt.tenant_id,p_target_kind,v_doc_id,v_receipt.id,v_line_id,v_line,v_amount);
   v_total := v_total+v_amount;
   v_count := v_count+1;
 end loop;
 if v_count=0 then raise exception '未选中有效收料明细' using errcode='22023'; end if;
 update public.scm_receipt_target_document set total_amount=v_total where id=v_doc_id;
 return v_doc_id;
end $$;


ALTER FUNCTION "public"."scm_push_receipt_lines_secure"("p_receipt_id" "uuid", "p_line_ids" "uuid"[], "p_target_kind" "text") OWNER TO "postgres";

--

--
-- Name: scm_transition_receipt_target_secure("uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."scm_transition_receipt_target_secure"("p_target_id" "uuid", "p_action" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
 v_doc public.scm_receipt_target_document%rowtype;
 v_line public.scm_receipt_target_line%rowtype;
 v_data jsonb;
 v_qty numeric;
 v_batch_id uuid;
 v_warehouse_id uuid;
 v_material_id uuid;
 v_bin_id uuid;
 v_owner_type text;
 v_owner_id uuid;
 v_batch_no text;
 v_unit_cost numeric;
 v_serial_enabled boolean;
 v_movement_id uuid;
begin
 select * into v_doc from public.scm_receipt_target_document where id=p_target_id for update;
 if not found then raise exception '目标单据不存在' using errcode='22023'; end if;
 perform app_private.wms_resolve_write_tenant_id(v_doc.tenant_id);
 if v_doc.status<>'draft' then raise exception '仅草稿可执行确认或审核' using errcode='23514'; end if;
 if v_doc.target_kind='inbound' then
   perform app_private.wms_assert_project_section(v_doc.tenant_id,v_doc.project_id,v_doc.construction_no,false);
   if p_action<>'confirm' or not app_private.has_permission('WmsReceiptInbound:Confirm') then
     raise exception '没有确认入库权限' using errcode='42501';
   end if;
   for v_line in select * from public.scm_receipt_target_line
       where target_document_id=v_doc.id order by created_at,id loop
     v_data := v_line.line_snapshot;
     v_warehouse_id := nullif(v_data->>'warehouse_id','')::uuid;
     v_bin_id := nullif(v_data->>'bin_id','')::uuid;
     v_material_id := nullif(v_data->>'material_id','')::uuid;
     if v_warehouse_id is null or v_material_id is null then
       raise exception '确认入库前须补齐仓库与物料' using errcode='23514';
     end if;
     v_qty := app_private.scm_receipt_stock_quantity(
       v_doc.tenant_id,v_material_id,coalesce((v_data->>'quantity')::numeric,0));
     if v_qty<=0 then raise exception '库存单位数量必须大于零' using errcode='23514'; end if;
     select serial_management_enabled into v_serial_enabled from public.mdm_material
       where id=v_material_id and tenant_id=v_doc.tenant_id;
     if coalesce(v_serial_enabled,false) then
       if v_qty<>trunc(v_qty) or cardinality(v_line.serial_nos)<>v_qty
         or exists(select 1 from unnest(v_line.serial_nos) sn where btrim(sn)='' or length(sn)>100)
         or (select count(distinct sn) from unnest(v_line.serial_nos) sn)<>cardinality(v_line.serial_nos) then
        raise exception 'SN 物料收料入库须逐行录入与库存数量一致的唯一序列号' using errcode='23514'; end if;
     elsif cardinality(v_line.serial_nos)>0 then
       raise exception '未启用 SN 管理的物料不能录入序列号' using errcode='23514';
     end if;
     v_owner_type := coalesce(nullif(v_data->>'owner_type',''),'self');
     v_owner_id := nullif(v_data->>'owner_id','')::uuid;
     if v_owner_type='self' then
       v_owner_id := null;
     elsif v_owner_type='supplier' then
       if v_owner_id is null or not exists (
         select 1 from public.mdm_supplier where id=v_owner_id and tenant_id=v_doc.tenant_id) then
         raise exception '货主供应商不属于当前租户' using errcode='23514';
       end if;
     elsif v_owner_type='customer' then
       if v_owner_id is null or not exists (
         select 1 from public.mdm_customer where id=v_owner_id and tenant_id=v_doc.tenant_id) then
         raise exception '货主客户不属于当前租户' using errcode='23514';
       end if;
     else
       raise exception '无效的货主类型' using errcode='23514';
     end if;
     v_batch_no := coalesce(nullif(v_data->>'batch_no',''),
       left(v_doc.document_no||'-'||coalesce(v_data->>'line_no','1'),80));
     v_unit_cost := case when coalesce((v_data->>'gift')::boolean,false) then 0 else
       round(round((v_data->>'quantity')::numeric
         * coalesce((v_data->>'unit_price')::numeric,0)
         * (1-coalesce((v_data->>'discount_rate')::numeric,0)/100),2) / v_qty,4)
       end;
     perform app_private.assert_wms_destination(v_doc.tenant_id,v_warehouse_id,v_bin_id,v_material_id,v_qty,null);
     select id into v_batch_id from public.wms_inventory_batch
     where tenant_id=v_doc.tenant_id and warehouse_id=v_warehouse_id
       and bin_id is not distinct from v_bin_id and material_id=v_material_id
       and batch_no=v_batch_no and owner_type=v_owner_type
       and owner_id is not distinct from v_owner_id and status='normal'
       and project_id is not distinct from v_doc.project_id
       and construction_no is not distinct from v_doc.construction_no
     order by received_at limit 1 for update;
     if found then
       update public.wms_inventory_batch set quantity=quantity+v_qty,
         last_movement_at=now() where id=v_batch_id;
     else
       insert into public.wms_inventory_batch
         (tenant_id,warehouse_id,bin_id,material_id,batch_no,quantity,
          unit_cost,received_at,last_movement_at,owner_type,owner_id,project_id,construction_no)
       values (v_doc.tenant_id,v_warehouse_id,v_bin_id,v_material_id,v_batch_no,v_qty,
         v_unit_cost,now(),now(),v_owner_type,v_owner_id,v_doc.project_id,v_doc.construction_no)
       returning id into v_batch_id;
     end if;
     insert into public.wms_inventory_movement
       (tenant_id,movement_type,target_batch_id,material_id,quantity,unit_cost,reference_no,occurred_at,remark)
     values (v_doc.tenant_id,'receipt_inbound',v_batch_id,v_material_id,v_qty,
       v_unit_cost,v_doc.document_no,now(),
       '收料通知单下推：'||v_doc.source_receipt_id::text)
     returning id into v_movement_id;
     if coalesce(v_serial_enabled,false) then
       insert into public.wms_serial_number(
        tenant_id,serial_no,material_id,batch_id,status,warehouse_id,bin_id)
       select v_doc.tenant_id,sn,v_material_id,v_batch_id,'in_stock',v_warehouse_id,v_bin_id
       from unnest(v_line.serial_nos) sn;
       insert into public.wms_serial_movement(tenant_id,movement_id,serial_id)
       select v_doc.tenant_id,v_movement_id,s.id from public.wms_serial_number s
       where s.tenant_id=v_doc.tenant_id and s.batch_id=v_batch_id
         and s.serial_no=any(v_line.serial_nos);
     end if;
   end loop;
   update public.scm_receipt_target_document set status='confirmed',completed_at=now(),updated_at=now()
     where id=v_doc.id;
 else
   if p_action<>'approve' or not app_private.has_permission('FinanceAssetPayable:Approve') then
     raise exception '没有审核应付权限' using errcode='42501';
   end if;
   update public.scm_receipt_target_document set status='approved',completed_at=now(),updated_at=now()
     where id=v_doc.id;
 end if;
end $$;


ALTER FUNCTION "public"."scm_transition_receipt_target_secure"("p_target_id" "uuid", "p_action" "text") OWNER TO "postgres";

