--

--
-- Name: start_workflow("text", "uuid", "text", "jsonb", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb" DEFAULT '{}'::"jsonb", "p_idempotency_key" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_instance_id uuid;
  v_context jsonb := coalesce(p_context, '{}'::jsonb);
  v_title text := p_business_title;
begin
  if app_private.is_driver_user() then
    raise exception '司机端请通过对应的业务上报入口提交审批'
      using errcode = '42501';
  end if;
  if p_business_type = 'tms_waybill_cost' then
    perform public.validate_tms_waybill_cost_submission_secure(p_business_id);
  elsif p_business_type = 'tms_expense_reimbursement' then
    v_context := v_context ||
      public.validate_tms_expense_reimbursement_submission_secure(p_business_id);
    v_title := '费用报销 ' || coalesce(v_context->>'reimbursementNo', p_business_id::text);
  end if;
  v_instance_id := app_private.start_workflow(
    p_business_type, p_business_id, v_title, v_context, p_idempotency_key
  );
  if p_business_type = 'tms_waybill_cost' then
    update public.wf_instance
    set context_snapshot = coalesce(context_snapshot, '{}'::jsonb) - 'amount'
    where id = v_instance_id
      and business_type = 'tms_waybill_cost'
      and tenant_id = app_private.current_user_tenant_id();
  elsif p_business_type = 'tms_expense_reimbursement' then
    update public.wf_instance
    set business_title = v_title,
        context_snapshot = coalesce(context_snapshot, '{}'::jsonb)
          - 'amount'
          - 'paymentMethod'
          - 'payeeName'
          - 'payeeBank'
          - 'payeeAccount'
    where id = v_instance_id
      and business_type = 'tms_expense_reimbursement'
      and tenant_id = app_private.current_user_tenant_id();
  end if;
  return v_instance_id;
end;
$$;


ALTER FUNCTION "public"."start_workflow"("p_business_type" "text", "p_business_id" "uuid", "p_business_title" "text", "p_context" "jsonb", "p_idempotency_key" "text") OWNER TO "postgres";

--

--
-- Name: test_notification_channel("uuid", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."test_notification_channel"("p_tenant_id" "uuid", "p_channel_code" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.notification_target_tenant(p_tenant_id);
  v_user_id uuid := app_private.current_app_user_id();
  v_delivery_id uuid;
begin
  if not app_private.has_permission('System:NotificationReminder:TestChannel') then
    raise exception '缺少测试通知渠道权限' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.sys_notification_channel_config
    where tenant_id = v_tenant_id and channel_code = p_channel_code
      and (channel_code = 'in_app' or vault_secret_id is not null)
  ) then raise exception '请先完成该渠道的凭据配置'; end if;

  if not exists (
    select 1 from public.sys_user where id = v_user_id and tenant_id = v_tenant_id
  ) then
    select user_row.id into v_user_id
    from public.sys_user user_row
    where user_row.tenant_id = v_tenant_id
      and user_row.status = '1'
      and user_row.deleted_at is null
      and exists (
        select 1 from public.sys_role role_row
        where role_row.tenant_id = user_row.tenant_id
          and role_row.enabled is true
          and role_row.role_code = any(coalesce(user_row.user_roles, array[]::text[]))
          and role_row.role_code in ('R_ADMIN', 'YQ_ADMIN', 'R_SUPER')
      )
    order by user_row.create_time
    limit 1;
  end if;
  if v_user_id is null then raise exception '目标租户没有可用的管理员账号'; end if;

  insert into public.sys_notification_delivery (
    tenant_id, recipient_user_id, channel_code, title, content, route_path,
    status, create_by, update_by
  ) values (
    v_tenant_id, v_user_id, p_channel_code, '通知渠道测试',
    '这是一条渠道连通性测试消息，发送时间：' || to_char(now() at time zone 'Asia/Shanghai', 'YYYY-MM-DD HH24:MI:SS'),
    '/system/notification-reminder', 'pending',
    coalesce(app_private.current_user_email(), 'system-reminder'),
    coalesce(app_private.current_user_email(), 'system-reminder')
  ) returning id into v_delivery_id;

  update public.sys_notification_channel_config
  set last_test_at = now(), last_test_status = 'pending', last_error = null,
      update_by = coalesce(app_private.current_user_email(), 'system-reminder')
  where tenant_id = v_tenant_id and channel_code = p_channel_code;

  if p_channel_code = 'in_app' then
    perform app_private.enqueue_user_notification(
      v_user_id, v_tenant_id, 'message', '通知渠道测试', '站内通知渠道已连通。',
      'success', 'notification_channel_test', v_delivery_id,
      'notification_channel', v_delivery_id, null, '/system/notification-reminder', '{}'::jsonb
    );
    update public.sys_notification_delivery
    set status = 'delivered', delivered_at = now(), attempt_count = 1, update_by = 'system-reminder'
    where id = v_delivery_id;
    update public.sys_notification_channel_config
    set last_test_status = 'delivered', update_by = 'system-reminder'
    where tenant_id = v_tenant_id and channel_code = p_channel_code;
  end if;
  return v_delivery_id;
end;
$$;


ALTER FUNCTION "public"."test_notification_channel"("p_tenant_id" "uuid", "p_channel_code" "text") OWNER TO "postgres";

--

--
-- Name: tms_get_invoice_compliance_audit_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."tms_get_invoice_compliance_audit_secure"("p_invoice_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_invoice public.tms_invoice%rowtype;
  v_access jsonb;
  v_statement_links jsonb;
  v_duplicates jsonb;
begin
  if not app_private.can_execute_business_action(
    'FinanceInvoiceManagement', 'FinanceInvoiceManagement:AiAudit', null, false
  ) then
    raise exception 'Missing invoice AI audit permission' using errcode = '42501';
  end if;

  select invoice_row.*
  into v_invoice
  from public.tms_invoice invoice_row
  where invoice_row.id = p_invoice_id
    and (app_private.current_read_tenant_id() is null or invoice_row.tenant_id = app_private.current_read_tenant_id());

  if not found then
    return null;
  end if;

  v_access := app_private.field_access_map('tms.invoice', v_invoice.created_by_user_id);
  if coalesce(v_access->>'invoiceAmounts', 'hidden') not in ('read', 'edit')
     or coalesce(v_access->>'taxIdentity', 'hidden') not in ('read', 'edit')
     or coalesce(v_access->>'invoiceAttachments', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取发票金额、税号或附件进行合规审核'
      using errcode = '42501';
  end if;

  if exists (
    select 1
    from public.tms_invoice_statement_link link_row
    left join public.tms_customer_statement customer_statement
      on link_row.customer_statement_id = customer_statement.id
     and link_row.tenant_id = customer_statement.tenant_id
    left join public.tms_carrier_statement carrier_statement
      on link_row.carrier_statement_id = carrier_statement.id
     and link_row.tenant_id = carrier_statement.tenant_id
    where link_row.invoice_id = p_invoice_id
      and (
        (
          link_row.customer_statement_id is not null
          and app_private.resolve_field_access(
            'tms.customer_statement', 'statementAmounts', customer_statement.created_by_user_id
          ) not in ('read', 'edit')
        )
        or (
          link_row.carrier_statement_id is not null
          and app_private.resolve_field_access(
            'tms.carrier_statement', 'statementAmounts', carrier_statement.created_by_user_id
          ) not in ('read', 'edit')
        )
      )
  ) then
    raise exception '当前字段权限不足，无法读取关联对账金额进行合规审核'
      using errcode = '42501';
  end if;

  select coalesce(jsonb_agg(to_jsonb(link_row) - 'tenant_id'
    order by link_row.period_end, link_row.id), '[]'::jsonb)
  into v_statement_links
  from public.tms_invoice_detail_link link_row
  where link_row.invoice_id = p_invoice_id
    and link_row.tenant_id = v_invoice.tenant_id;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', duplicate_row.id,
    'status', duplicate_row.status,
    'invoice_record_no', duplicate_row.invoice_record_no,
    'invoice_code', duplicate_row.invoice_code,
    'invoice_no', duplicate_row.invoice_no
  ) order by duplicate_row.create_time, duplicate_row.id), '[]'::jsonb)
  into v_duplicates
  from public.tms_invoice duplicate_row
  where duplicate_row.tenant_id = v_invoice.tenant_id
    and duplicate_row.id <> v_invoice.id
    and duplicate_row.status <> 'voided'
    and duplicate_row.invoice_no = v_invoice.invoice_no
    and (
      nullif(v_invoice.invoice_code, '') is null
      or duplicate_row.invoice_code = v_invoice.invoice_code
    );

  return jsonb_build_object(
    'invoice', to_jsonb(v_invoice) - 'tenant_id' - 'created_by_user_id',
    'statementLinks', v_statement_links,
    'duplicateInvoices', v_duplicates
  );
end;
$$;


ALTER FUNCTION "public"."tms_get_invoice_compliance_audit_secure"("p_invoice_id" "uuid") OWNER TO "postgres";

--

--
-- Name: tms_get_waybill_cost_ai_evidence_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."tms_get_waybill_cost_ai_evidence_secure"("p_cost_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cost public.tms_waybill_cost%rowtype;
  v_access jsonb;
  v_cost_json jsonb;
  v_siblings jsonb;
  v_references jsonb;
  v_profit jsonb;
  v_profit_owner uuid;
begin
  if not app_private.can_execute_business_action(
    'FinanceWaybillCost', 'FinanceWaybillCost:AiAudit', null, false
  ) then
    raise exception 'Missing waybill cost AI audit permission' using errcode = '42501';
  end if;
  select cost_row.* into v_cost
  from public.tms_waybill_cost cost_row
  where cost_row.id = p_cost_id and (app_private.current_read_tenant_id() is null or cost_row.tenant_id = app_private.current_read_tenant_id());
  if not found then return null; end if;
  v_access := app_private.field_access_map('tms.waybill_cost', v_cost.created_by_user_id);
  if coalesce(v_access->>'costAmounts', 'hidden') not in ('read', 'edit')
     or coalesce(v_access->>'paymentDetails', 'hidden') not in ('read', 'edit')
     or coalesce(v_access->>'expenseEvidence', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取费用金额、收款信息或票据依据进行 AI 审核'
      using errcode = '42501';
  end if;

  select (to_jsonb(v_cost) - 'tenant_id' - 'created_by_user_id') || jsonb_build_object(
    'waybill', jsonb_build_object(
      'id', waybill_row.id,
      'waybill_no', waybill_row.waybill_no,
      'origin_city', waybill_row.origin_city,
      'destination_city', waybill_row.destination_city,
      'order', case when order_row.id is null then null else jsonb_build_object(
        'id', order_row.id,
        'origin_station', order_row.origin_station,
        'destination_station', order_row.destination_station
      ) end
    )
  ) into v_cost_json
  from public.tms_waybill waybill_row
  left join public.tms_order order_row on order_row.id = waybill_row.order_id
  where waybill_row.id = v_cost.waybill_id and (app_private.current_read_tenant_id() is null or waybill_row.tenant_id = app_private.current_read_tenant_id());

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', sibling.id,
    'waybill_id', sibling.waybill_id,
    'cost_type', sibling.cost_type,
    'amount', sibling.amount,
    'occurred_on', sibling.occurred_on,
    'payee_name', case
      when app_private.resolve_field_access(
        'tms.waybill_cost', 'paymentDetails', sibling.created_by_user_id
      ) in ('read', 'edit') then sibling.payee_name else null end,
    'audit_status', sibling.audit_status
  ) order by sibling.occurred_on desc, sibling.id), '[]'::jsonb)
  into v_siblings
  from public.tms_waybill_cost sibling
  where (app_private.current_read_tenant_id() is null or sibling.tenant_id = app_private.current_read_tenant_id())
    and sibling.waybill_id = v_cost.waybill_id
    and app_private.resolve_field_access(
      'tms.waybill_cost', 'costAmounts', sibling.created_by_user_id
    ) in ('read', 'edit');

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', reference_row.id, 'amount', reference_row.amount
  ) order by reference_row.occurred_on desc, reference_row.id), '[]'::jsonb)
  into v_references
  from (
    select cost_row.*
    from public.tms_waybill_cost cost_row
    where (app_private.current_read_tenant_id() is null or cost_row.tenant_id = app_private.current_read_tenant_id())
      and cost_row.cost_type = v_cost.cost_type
      and cost_row.audit_status = 'approved'
      and app_private.resolve_field_access(
        'tms.waybill_cost', 'costAmounts', cost_row.created_by_user_id
      ) in ('read', 'edit')
    order by cost_row.occurred_on desc, cost_row.id
    limit 100
  ) reference_row;

  select waybill_row.created_by_user_id into v_profit_owner
  from public.tms_waybill waybill_row
  where waybill_row.id = v_cost.waybill_id and (app_private.current_read_tenant_id() is null or waybill_row.tenant_id = app_private.current_read_tenant_id());
  if app_private.resolve_field_access(
       'tms.waybill_profit', 'receivableAmounts', v_profit_owner
     ) in ('read', 'edit')
     and app_private.resolve_field_access(
       'tms.waybill_profit', 'costAmounts', v_profit_owner
     ) in ('read', 'edit')
     and app_private.resolve_field_access(
       'tms.waybill_profit', 'profitAmounts', v_profit_owner
     ) in ('read', 'edit') then
    select to_jsonb(profit_row) - 'tenant_id' into v_profit
    from public.tms_waybill_profit profit_row
    where (app_private.current_read_tenant_id() is null or profit_row.tenant_id = app_private.current_read_tenant_id())
      and profit_row.waybill_id = v_cost.waybill_id;
  end if;

  return jsonb_build_object(
    'cost', v_cost_json,
    'sibling_costs', v_siblings,
    'reference_costs', v_references,
    'profit', v_profit
  );
end;
$$;


ALTER FUNCTION "public"."tms_get_waybill_cost_ai_evidence_secure"("p_cost_id" "uuid") OWNER TO "postgres";

--

--
-- Name: tms_get_waybill_profit_ai_evidence_secure(integer); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."tms_get_waybill_profit_ai_evidence_secure"("p_limit" integer DEFAULT 300) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
begin
  if not app_private.can_execute_business_action(
    'FinanceWaybillProfit', 'FinanceWaybillProfit:AiProfitAnalysis', null, false
  ) then
    raise exception 'Missing waybill profit AI permission' using errcode = '42501';
  end if;
  return coalesce((
    select jsonb_agg(to_jsonb(permitted) - 'created_by_user_id'
      order by permitted.create_time desc, permitted.id)
    from (
      select profit_row.*, waybill_row.created_by_user_id
      from public.tms_waybill_profit profit_row
      join public.tms_waybill waybill_row
        on waybill_row.id = profit_row.waybill_id
       and waybill_row.tenant_id = profit_row.tenant_id
      where (app_private.current_read_tenant_id() is null or profit_row.tenant_id = app_private.current_read_tenant_id())
        and profit_row.waybill_status <> 'cancelled'
        and app_private.resolve_field_access(
          'tms.waybill_profit', 'receivableAmounts', waybill_row.created_by_user_id
        ) in ('read', 'edit')
        and app_private.resolve_field_access(
          'tms.waybill_profit', 'costAmounts', waybill_row.created_by_user_id
        ) in ('read', 'edit')
        and app_private.resolve_field_access(
          'tms.waybill_profit', 'profitAmounts', waybill_row.created_by_user_id
        ) in ('read', 'edit')
      order by profit_row.create_time desc, profit_row.id
      limit least(300, greatest(coalesce(p_limit, 300), 1))
    ) permitted
  ), '[]'::jsonb);
end;
$$;


