CREATE OR REPLACE FUNCTION "public"."tms_list_customer_statement_allocatable_secure"("p_customer_id" "uuid", "p_keyword" "text" DEFAULT NULL::"text", "p_from" integer DEFAULT 0, "p_to" integer DEFAULT 9) RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
