--
-- Name: ai_feedback_resolution; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."ai_feedback_resolution" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "feedback_id" bigint NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "issue_type" "text",
    "resolution_note" "text",
    "handled_by" "uuid" DEFAULT "auth"."uid"() NOT NULL,
    "resolved_by" "uuid",
    "resolved_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    CONSTRAINT "ai_feedback_resolution_closed_audit_check" CHECK (((("status" = ANY (ARRAY['resolved'::"text", 'dismissed'::"text"])) AND ("resolved_by" IS NOT NULL) AND ("resolved_at" IS NOT NULL)) OR (("status" <> ALL (ARRAY['resolved'::"text", 'dismissed'::"text"])) AND ("resolved_by" IS NULL) AND ("resolved_at" IS NULL)))),
    CONSTRAINT "ai_feedback_resolution_closed_note_check" CHECK ((("status" <> ALL (ARRAY['resolved'::"text", 'dismissed'::"text"])) OR ("length"(TRIM(BOTH FROM COALESCE("resolution_note", ''::"text"))) >= 3))),
    CONSTRAINT "ai_feedback_resolution_issue_type_check" CHECK ((("issue_type" IS NULL) OR ("issue_type" = ANY (ARRAY['incorrect'::"text", 'incomplete'::"text", 'irrelevant'::"text", 'unsafe'::"text", 'slow'::"text", 'data_quality'::"text", 'other'::"text"])))),
    CONSTRAINT "ai_feedback_resolution_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'resolved'::"text", 'dismissed'::"text"])))
);


ALTER TABLE "public"."ai_feedback_resolution" OWNER TO "postgres";

--

--
-- Name: upsert_ai_feedback_resolution(bigint, "text", "text", "text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."upsert_ai_feedback_resolution"("p_feedback_id" bigint, "p_status" "text", "p_issue_type" "text" DEFAULT NULL::"text", "p_resolution_note" "text" DEFAULT NULL::"text") RETURNS "public"."ai_feedback_resolution"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  target_tenant_id uuid;
  result public.ai_feedback_resolution;
  normalized_note text := nullif(trim(coalesce(p_resolution_note, '')), '');
begin
  if (select auth.uid()) is null then
    raise exception 'Authentication required';
  end if;

  if not (
    (select app_private.is_platform_super())
    or (select app_private.is_tenant_admin())
  ) then
    raise exception 'Only platform or tenant administrators can handle AI feedback';
  end if;

  select feedback.tenant_id
  into target_tenant_id
  from public.ai_feedback feedback
  where feedback.id = p_feedback_id;

  if target_tenant_id is null then
    raise exception 'AI feedback does not exist or is outside the current scope';
  end if;

  insert into public.ai_feedback_resolution (
    feedback_id,
    status,
    issue_type,
    resolution_note,
    handled_by,
    resolved_by,
    resolved_at,
    tenant_id
  ) values (
    p_feedback_id,
    p_status,
    p_issue_type,
    normalized_note,
    (select auth.uid()),
    case when p_status in ('resolved', 'dismissed') then (select auth.uid()) else null end,
    case when p_status in ('resolved', 'dismissed') then current_timestamp else null end,
    target_tenant_id
  )
  on conflict (feedback_id) do update
  set status = excluded.status,
      issue_type = excluded.issue_type,
      resolution_note = excluded.resolution_note,
      handled_by = excluded.handled_by,
      resolved_by = excluded.resolved_by,
      resolved_at = excluded.resolved_at
  returning * into result;

  return result;
end;
$$;


ALTER FUNCTION "public"."upsert_ai_feedback_resolution"("p_feedback_id" bigint, "p_status" "text", "p_issue_type" "text", "p_resolution_note" "text") OWNER TO "postgres";

--

--
-- Name: validate_tms_carrier_payment_application_submission("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_app record;
  v_item record;
  v_item_count integer;
  v_total numeric(14,2);
  v_outstanding numeric(14,2);
  v_reserved numeric(14,2);
begin
  select * into v_app from public.tms_carrier_payment_application
  where id=p_application_id for update;
  if not found then raise exception '付款申请不存在'; end if;
  if v_app.status not in ('draft','rejected') then raise exception '只有草稿或已驳回申请可以提交审批'; end if;
  if not app_private.is_platform_super() and v_app.tenant_id is distinct from app_private.current_user_tenant_id() then
    raise exception '无权提交其他租户付款申请';
  end if;
  select count(*)::integer, coalesce(sum(applied_amount),0)::numeric(14,2)
  into v_item_count, v_total
  from public.tms_carrier_payment_application_item where application_id=p_application_id;
  if v_item_count < 1 then raise exception '请至少选择一份待付款对账单'; end if;
  if v_total is distinct from v_app.amount then raise exception '付款分配合计必须等于申请金额'; end if;

  for v_item in
    select i.*, s.status statement_status, s.settled_amount,
      coalesce((select sum(si.line_amount) from public.tms_carrier_statement_item si
                where si.statement_id=s.id and si.is_active),0)::numeric(14,2) statement_amount
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_statement s on s.id=i.statement_id
    where i.application_id=p_application_id order by i.statement_id
  loop
    perform pg_advisory_xact_lock(hashtextextended(v_item.statement_id::text, 841329));
    if v_item.statement_status not in ('confirmed','partially_settled') then
      raise exception '对账单 % 当前状态不允许付款', v_item.statement_no_snapshot;
    end if;
    v_outstanding := greatest(v_item.statement_amount-v_item.settled_amount,0)::numeric(14,2);
    select coalesce(sum(i.applied_amount),0)::numeric(14,2) into v_reserved
    from public.tms_carrier_payment_application_item i
    join public.tms_carrier_payment_application a on a.id=i.application_id
    where i.statement_id=v_item.statement_id
      and a.status in ('pending_review','approved')
      and a.id<>p_application_id;
    if v_item.applied_amount > v_outstanding-v_reserved then
      raise exception '对账单 % 可申请余额不足，当前可申请 %',
        v_item.statement_no_snapshot, greatest(v_outstanding-v_reserved,0);
    end if;
  end loop;
  return true;
end;
$$;


ALTER FUNCTION "public"."validate_tms_carrier_payment_application_submission"("p_application_id" "uuid") OWNER TO "postgres";

--

--
-- Name: validate_tms_expense_reimbursement_submission_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_expense_reimbursement_submission_secure"("p_reimbursement_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_reimbursement public.tms_expense_reimbursement%rowtype;
  v_access jsonb;
begin
  select reimbursement_row.*
  into v_reimbursement
  from public.tms_expense_reimbursement reimbursement_row
  where reimbursement_row.id = p_reimbursement_id
    and reimbursement_row.tenant_id = v_tenant_id;
  if not found then raise exception '费用报销单不存在或无权访问'; end if;
  if v_reimbursement.status not in ('draft', 'rejected') then
    raise exception '当前费用报销单状态不允许提交审批';
  end if;
  v_access := app_private.field_access_map(
    'tms.expense_reimbursement', v_reimbursement.created_by_user_id
  );
  if coalesce(v_access->>'reimbursementAmounts', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取报销金额并提交审批'
      using errcode = '42501';
  end if;
  if coalesce(v_access->>'payeeDetails', 'hidden') not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取收款信息并提交审批'
      using errcode = '42501';
  end if;
  return jsonb_build_object(
    'amount', v_reimbursement.total_amount,
    'reimbursementNo', v_reimbursement.reimbursement_no,
    'paymentMethod', v_reimbursement.payment_method,
    'plannedPaymentDate', v_reimbursement.planned_payment_date,
    'itemCount', (
      select count(*)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        and item_row.tenant_id = v_reimbursement.tenant_id
    ),
    'waybillCount', (
      select count(distinct item_row.waybill_id)::integer
      from public.tms_expense_reimbursement_item item_row
      where item_row.reimbursement_id = v_reimbursement.id
        and item_row.tenant_id = v_reimbursement.tenant_id
    )
  );
end;
$$;


ALTER FUNCTION "public"."validate_tms_expense_reimbursement_submission_secure"("p_reimbursement_id" "uuid") OWNER TO "postgres";

--

--
-- Name: validate_tms_waybill_cost_submission_secure("uuid"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."validate_tms_waybill_cost_submission_secure"("p_cost_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_tenant_id uuid := app_private.current_user_tenant_id();
  v_cost public.tms_waybill_cost%rowtype;
begin
  if not app_private.can_execute_business_action(
    'FinanceWaybillCost', 'FinanceWaybillCost:Submit', null, false
  ) then
    raise exception 'Missing waybill cost submit permission' using errcode = '42501';
  end if;
  select cost_row.* into v_cost
  from public.tms_waybill_cost cost_row
  where cost_row.id = p_cost_id and cost_row.tenant_id = v_tenant_id;
  if not found then raise exception '运单费用不存在或无权访问'; end if;
  if v_cost.audit_status not in ('draft', 'rejected') then
    raise exception '当前运单费用状态不允许提交审批';
  end if;
  if app_private.resolve_field_access(
    'tms.waybill_cost', 'costAmounts', v_cost.created_by_user_id
  ) not in ('read', 'edit') then
    raise exception '当前字段权限不足，无法读取费用金额并提交审批'
      using errcode = '42501';
  end if;
  return true;
end;
$$;


ALTER FUNCTION "public"."validate_tms_waybill_cost_submission_secure"("p_cost_id" "uuid") OWNER TO "postgres";

--

--
-- Name: verify_notification_dispatch_token("text"); Type: FUNCTION; Schema: public
--

--

CREATE OR REPLACE FUNCTION "public"."verify_notification_dispatch_token"("p_token" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce((select auth.jwt() ->> 'role'), '') = 'service_role'
    and exists (
      select 1 from vault.decrypted_secrets
      where name = 'notification_dispatch_cron_token'
        and decrypted_secret = p_token
    );
$$;


ALTER FUNCTION "public"."verify_notification_dispatch_token"("p_token" "text") OWNER TO "postgres";

