CREATE TABLE IF NOT EXISTS "public"."tms_invoice" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    "invoice_record_no" "text" NOT NULL,
    "direction" "text" NOT NULL,
    "invoice_type" "text" NOT NULL,
    "customer_id" "uuid",
    "carrier_id" "uuid",
    "counterparty_name_snapshot" "text" NOT NULL,
    "invoice_title" "text",
    "tax_number" "text",
    "invoice_code" "text",
    "invoice_no" "text",
    "issue_date" "date" DEFAULT CURRENT_DATE NOT NULL,
    "tax_rate" numeric(7,4) DEFAULT 0 NOT NULL,
    "amount_excluding_tax" numeric(14,2) NOT NULL,
    "tax_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "total_amount" numeric(14,2) NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "attachments" "jsonb" DEFAULT '[]'::"jsonb" NOT NULL,
    "submitted_at" timestamp with time zone,
    "submitted_by" "text",
    "reviewed_at" timestamp with time zone,
    "reviewed_by" "text",
    "review_remark" "text",
    "voided_at" timestamp with time zone,
    "voided_by" "text",
    "void_reason" "text",
    "remark" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "created_by_user_id" "uuid" NOT NULL,
    CONSTRAINT "tms_invoice_amount_check" CHECK ((("amount_excluding_tax" >= (0)::numeric) AND ("tax_amount" >= (0)::numeric) AND ("total_amount" > (0)::numeric) AND ("abs"((("amount_excluding_tax" + "tax_amount") - "total_amount")) <= 0.01))),
    CONSTRAINT "tms_invoice_attachments_check" CHECK (("jsonb_typeof"("attachments") = 'array'::"text")),
    CONSTRAINT "tms_invoice_counterparty_check" CHECK (((("direction" = 'output'::"text") AND ("customer_id" IS NOT NULL) AND ("carrier_id" IS NULL)) OR (("direction" = 'input'::"text") AND ("carrier_id" IS NOT NULL) AND ("customer_id" IS NULL)))),
    CONSTRAINT "tms_invoice_counterparty_name_check" CHECK (("btrim"("counterparty_name_snapshot") <> ''::"text")),
    CONSTRAINT "tms_invoice_direction_check" CHECK (("direction" = ANY (ARRAY['output'::"text", 'input'::"text"]))),
    CONSTRAINT "tms_invoice_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'pending_review'::"text", 'issued'::"text", 'certified'::"text", 'voided'::"text"]))),
    CONSTRAINT "tms_invoice_tax_rate_check" CHECK ((("tax_rate" >= (0)::numeric) AND ("tax_rate" <= (100)::numeric))),
    CONSTRAINT "tms_invoice_type_check" CHECK (("invoice_type" = ANY (ARRAY['vat_special'::"text", 'vat_ordinary'::"text", 'electronic'::"text"])))
);


