    "scheduled_at" timestamp with time zone NOT NULL,
    "due_at" timestamp with time zone NOT NULL,
    "attempt_count" integer DEFAULT 0 NOT NULL,
    "last_attempt_at" timestamp with time zone,
    "next_retry_at" timestamp with time zone,
    "delivered_at" timestamp with time zone,
    "recipient_user_ids" "uuid"[] DEFAULT '{}'::"uuid"[] NOT NULL,
    "error_message" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" NOT NULL,
    CONSTRAINT "wf_task_reminder_attempt_count_check" CHECK ((("attempt_count" >= 0) AND ("attempt_count" <= 10))),
    CONSTRAINT "wf_task_reminder_event_type_check" CHECK (("event_type" = ANY (ARRAY['due_soon'::"text", 'overdue'::"text", 'manager_escalation'::"text"]))),
    CONSTRAINT "wf_task_reminder_status_check" CHECK (("status" = ANY (ARRAY['pending'::"text", 'delivered'::"text", 'failed'::"text"])))
);


ALTER TABLE "public"."wf_task_reminder_event" OWNER TO "postgres";

--

--
-- Name: TABLE "wf_task_reminder_event"; Type: COMMENT; Schema: public
--

--

COMMENT ON TABLE "public"."wf_task_reminder_event" IS 'Idempotent delivery ledger for due-soon, overdue, and manager escalation workflow reminders.';


--

--
-- Name: wf_version; Type: TABLE; Schema: public
--

--

CREATE TABLE IF NOT EXISTS "public"."wf_version" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "definition_id" "uuid" NOT NULL,
    "version_no" integer NOT NULL,
    "status" "text" DEFAULT 'draft'::"text" NOT NULL,
    "config" "jsonb" DEFAULT '{"nodes": []}'::"jsonb" NOT NULL,
    "change_note" "text",
    "published_at" timestamp with time zone,
    "published_by" "text",
    "create_by" "text",
    "create_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "update_by" "text",
    "update_time" timestamp with time zone DEFAULT "now"() NOT NULL,
    "tenant_id" "uuid" DEFAULT "app_private"."current_user_tenant_id"() NOT NULL,
    CONSTRAINT "wf_version_config_object" CHECK (("jsonb_typeof"("config") = 'object'::"text")),
    CONSTRAINT "wf_version_no_positive" CHECK (("version_no" > 0)),
    CONSTRAINT "wf_version_status_check" CHECK (("status" = ANY (ARRAY['draft'::"text", 'published'::"text", 'retired'::"text"])))
);


ALTER TABLE "public"."wf_version" OWNER TO "postgres";

--

--
-- Name: TABLE "wf_version"; Type: COMMENT; Schema: public
--

--

COMMENT ON TABLE "public"."wf_version" IS 'Immutable after publishing; stores the complete workflow configuration snapshot.';


