    WHEN 'sales_quotation'::"text" THEN ("app_private"."has_permission"('ScmSalesQuotationDoc:Edit'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Activate'::"text") OR "app_private"."has_permission"('ScmSalesQuotationDoc:Expire'::"text"))
    WHEN 'project_quotation'::"text" THEN ("app_private"."has_permission"('ScmProjectQuotation:Edit'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Activate'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Complete'::"text") OR "app_private"."has_permission"('ScmProjectQuotation:Close'::"text"))
